SailingGame.prototype.startStory=function(port){this.checkPort();if(port!==this.s.port)throw new Error('请亲自到访这座城市，聆听故事的开端。');if(!CITY_STORIES[port])throw new Error('这座城暂时没有新的篇章。');if(this.s.cityStories[port])throw new Error('已在你的城市篇章中记录。');this.s.cityStories[port]={stage:0,choice:null};this.log(`在${PORT_BY_ID[port].name}结识${CITY_STORIES[port].npc}，开启「${CITY_STORIES[port].title}」。`,'quest');};
SailingGame.prototype.objective=function(goal,port){let value=0,label='';const s=this.s;switch(goal.type){case'visit':value=Number(s.visited.includes(goal.id));label='亲自到访'+PORT_BY_ID[goal.id].name;break;case'deliver':value=s.port===port&&!s.voyage?(s.cargo[goal.id]?.qty||0):0;label=`在${PORT_BY_ID[port].name}交付 ${goal.qty} 箱${GOODS.find(g=>g.id===goal.id).name}`;break;case'sell':value=s.commerceLog[goal.at+':'+goal.id]?.sold||0;label=`在${PORT_BY_ID[goal.at].name}累计出售 ${goal.qty} 箱${GOODS.find(g=>g.id===goal.id).name}`;break;case'survey':value=s.surveys[port]||0;label=`在${PORT_BY_ID[port].name}附近完成 ${goal.qty} 次考察`;break;case'battle':value=s.battles;label=`累计赢得 ${goal.qty} 场海战`;break;case'atlas':value=Object.keys(s.atlas).length;label=`图鉴记录达到 ${goal.qty} 项`;break;case'upgrade':value=s.upgrades[goal.id];label=UPGRADES.find(u=>u.id===goal.id).name+`达到 ${goal.qty} 级`;break;}return{value,target:goal.qty,ready:value>=goal.qty,label};};
SailingGame.prototype.finishStory=function(port,choice='scholar'){this.checkPort();const st=CITY_STORIES[port],record=this.s.cityStories[port];if(!record||record.stage>=2)throw new Error('尚未接受这座城的篇章，或已经全部完成。');const chapter=st.chapters[record.stage];if(!chapter.goals.every(g=>this.objective(g,port).ready))throw new Error('仍有尚未完成的章节目标。');if(!['scholar','merchant'].includes(choice))throw new Error('请选择有效的回报。');for(const goal of chapter.goals){if(goal.type!=='deliver')continue;const old=this.s.cargo[goal.id],remain=old.qty-goal.qty;if(remain===0)delete this.s.cargo[goal.id];else this.s.cargo[goal.id]={qty:remain,cost:old.cost*remain/old.qty};}record.stage++;const final=record.stage===2;record.choice=final?choice:null;const gold=chapter.gold+(final&&choice==='merchant'?900:0),knowledge=chapter.knowledge+(final&&choice==='scholar'?35:0);this.s.gold+=gold;this.s.fame+=chapter.fame;this.s.knowledge+=knowledge;this.log(`完成${PORT_BY_ID[port].name}篇章「${chapter.title}」，获得 ${gold} G、${chapter.fame} 声望与 ${knowledge} 学识。`,'quest');this.notify('chapter',final?st.title:chapter.title,final?'城市故事已完成 · 一份跨海的友谊':'下一章节已开启',port);this.syncWorld();return{gold,knowledge,final};};
SailingGame.prototype.achievementValue=function(a){const s=this.s;return({ports:s.visited.length,profit:s.profit,battles:s.battles,atlas:Object.keys(s.atlas).length,continents:Object.keys(s.atlas).filter(k=>k.startsWith('continent:')).length,animals:Object.keys(s.atlas).filter(k=>k.startsWith('animal:')).length,seas:Object.keys(s.atlas).filter(k=>k.startsWith('sea:')).length,stories:Object.values(s.cityStories).reduce((n,c)=>n+c.stage,0),distance:s.distance,research:Object.values(s.research).reduce((a,b)=>a+b,0),survivor:s.survivor})[a.stat]||0;};
SailingGame.prototype.claimAchievement=function(id){const a=ACHIEVEMENTS.find(a=>a.id===id);if(!a||this.s.achievements.includes(id))throw new Error('这项成就已经领取或不存在。');if(this.achievementValue(a)<a.target)throw new Error('尚未达成这项成就。');this.s.achievements.push(id);this.s.gold+=a.gold;this.s.knowledge+=a.knowledge;this.s.fame+=3;this.log(`领取成就「${a.name}」：${a.gold} G 与 ${a.knowledge} 学识。`,'quest');this.syncWorld();return a;};
SailingGame.prototype.study=function(id){this.checkPort();const r=RESEARCH.find(r=>r.id===id);if(!r)throw new Error('未知研究。');const lv=this.s.research[id],cost=r.cost*(lv+1);if(lv>=r.max)throw new Error('这项研究已达到最高级。');if(this.s.knowledge<cost)throw new Error(`还需要 ${cost-this.s.knowledge} 点学识。探索新城市、考察与完成篇章都能获得学识。`);this.s.knowledge-=cost;this.s.research[id]++;this.log(`研究「${r.name}」提升至 ${lv+1} 级，消耗 ${cost} 学识。`);this.syncWorld();return cost;};
const originalValidate=validateSave;
validateSave=function(raw){const s=originalValidate(raw);const integer=(v,max,def=0)=>Number.isInteger(v)&&v>=0&&v<=max?v:def;s.expansion=2;s.knowledge=integer(raw.knowledge,1e8);s.survivor=integer(raw.survivor,1);s.atlas={};for(const id of Object.keys(DISCOVERY_BY_ID)){const r=raw.atlas?.[id];if(r&&Number.isInteger(r.day)&&r.day>=0)s.atlas[id]={day:Math.min(r.day,s.day),place:PORT_BY_ID[r.place]?r.place:'公海'};}s.cityStories={};for(const id of Object.keys(CITY_STORIES)){const r=raw.cityStories?.[id];if(r&&Number.isInteger(r.stage)&&r.stage>=0&&r.stage<=2)s.cityStories[id]={stage:r.stage,choice:['merchant','scholar'].includes(r.choice)?r.choice:null};}s.achievements=Array.isArray(raw.achievements)?[...new Set(raw.achievements.filter(id=>ACHIEVEMENTS.some(a=>a.id===id)))]:[];s.achievementNotified=Array.isArray(raw.achievementNotified)?[...new Set(raw.achievementNotified.filter(id=>ACHIEVEMENTS.some(a=>a.id===id)))]:[];s.research={};for(const r of RESEARCH)s.research[r.id]=integer(raw.research?.[r.id],r.max);s.surveys={};s.commerceLog={};for(const p of PORTS){s.surveys[p.id]=integer(raw.surveys?.[p.id],100000);for(const g of GOODS){const key=p.id+':'+g.id,r=raw.commerceLog?.[key];if(r)s.commerceLog[key]={bought:integer(r.bought,1e8),sold:integer(r.sold,1e8)};}}return s;};


