/* 人物值勤、对话记录与 v1/v2 存档迁移。 */
const portraitNewState=newState;
newState=function(){return Object.assign(portraitNewState(),{edition:3,officer:'mate',conversations:{}});};
const portraitValidate=validateSave;
function restorePortraitOfficer(s,raw){s.officer=OFFICER_BY_ID[raw.officer]&&raw.officer!=='captain'?raw.officer:'mate';}
validateSave=function(raw){const s=portraitValidate(raw);s.edition=3;s.officer=OFFICER_BY_ID[raw.officer]&&raw.officer!=='captain'?raw.officer:'mate';s.conversations={};for(const p of PORTS){const v=raw.conversations?.[p.id];if(v&&typeof v==='object')s.conversations[p.id]={met:!!v.met,history:!!v.history};}return s;};
for(const [key,id,transform]of[
 ['speed','navigator',v=>v*1.05],['guns','gunner',v=>v+4],['capacity','boatswain',v=>v+12],['wage','mate',v=>Math.max(1,Math.ceil(v*.85))],['dailySupply','cook',v=>Math.max(1,v-1)]
]){const prior=Object.getOwnPropertyDescriptor(SailingGame.prototype,key).get;Object.defineProperty(SailingGame.prototype,key,{get(){const v=prior.call(this);return this.s.officer===id?transform(v):v;},configurable:true});}
SailingGame.prototype.appoint=function(id){this.checkPort();if(!OFFICER_BY_ID[id]||id==='captain')throw Error('请选择一位可值勤的船员。');if(this.s.officer==='boatswain'&&id!=='boatswain'&&this.cargoCount>this.capacity-12)throw Error('货舱已使用水手长提供的额外空间，请先卖出部分货物。');if(this.s.officer===id)return false;this.s.officer=id;this.log(`${OFFICER_BY_ID[id].name}开始值勤：${OFFICER_BY_ID[id].perk}。`);return true;};
SailingGame.prototype.recordConversation=function(port,topic){this.checkPort();if(this.s.port!==port||!CITY_STORIES[port])throw Error('请抵达当地与这位人物交谈。');const r=this.s.conversations[port]||(this.s.conversations[port]={met:false,history:false});if(!r.met){r.met=true;this.log(`与${CITY_STORIES[port].npc}在${PORT_BY_ID[port].name}交谈。`);}if(topic==='history'&&!r.history){r.history=true;this.log(`${PORT_BY_ID[port].name} · 历史回声：${CITY_STORIES[port].history}`);}return r;};
const portraitSurvey=SailingGame.prototype.survey;
SailingGame.prototype.survey=function(){const result=portraitSurvey.call(this);if(this.s.officer==='doctor')this.s.morale=Math.min(100,this.s.morale+4);if(this.s.officer==='lookout')this.s.knowledge+=2;return result;};
const portraitRepair=SailingGame.prototype.repair;
SailingGame.prototype.repair=function(){const s=this.s;if(s.officer!=='carpenter')return portraitRepair.call(this);this.checkPort();const cost=(this.maxHull-s.hull)*4;if(s.gold<cost)throw Error('金币不足，无法完成修理。');s.gold-=cost;s.hull=this.maxHull;this.log(`沈木生带队修理船体，花费 ${cost} G。`);return cost;};


