const v4NewState=newState,v4ValidateSave=validateSave;
const LORE_TOPIC_IDS=['history','trade','culture','nature'];
newState=function(){const s=v4NewState();s.edition=4;return s;};
validateSave=function(raw){const s=v4ValidateSave(raw);s.edition=4;s.settings.instantText=!!raw.settings?.instantText;for(const p of PORTS){const previous=raw.conversations?.[p.id],r=s.conversations[p.id];if(!r)continue;r.topics={};for(const id of LORE_TOPIC_IDS){const t=previous?.topics?.[id];if(t&&typeof t==='object')r.topics[id]={read:!!t.read,index:Number.isSafeInteger(t.index)?Math.max(0,Math.min(1000,t.index)):0};}if(r.history&&!r.topics.history)r.topics.history={read:true,index:0};}return s;};
SailingGame.prototype.noteReading=function(port,topic,index,read=false){if(!LORE_TOPIC_IDS.includes(topic)||this.s.port!==port||this.s.voyage)return;const r=this.s.conversations[port]||(this.s.conversations[port]={met:true,history:false});r.topics=r.topics||{};const t=r.topics[topic]||(r.topics[topic]={index:0,read:false});t.index=Math.max(t.index,index);t.read=t.read||read;if(topic==='history'&&read)r.history=true;};
SailingGame.prototype.surveyPreview=function(){const s=this.s,p=PORT_BY_ID[s.port],officer=OFFICER_BY_ID[s.officer]||OFFICER_BY_ID.mate;return{port:p.id,place:p.name,days:1,supplies:4,wage:s.gold>=this.wage?this.wage:0,normalWage:this.wage,officer:officer.name,perk:officer.perk,morale:Math.min(100-s.morale,s.officer==='doctor'?6:2),extraKnowledge:s.officer==='lookout'?2:0,count:s.surveys[p.id]||0,canStart:!s.voyage&&s.supplies>=4,reason:s.voyage?'抵达港口后才能开展考察。':s.supplies<4?'还需要 '+(4-s.supplies)+' 单位补给。':''};};
SailingGame.prototype.surveyObjectives=function(port){const r=this.s.cityStories[port],ch=CITY_STORIES[port]?.chapters[r?.stage];if(!r||!ch)return null;return{port,stage:r.stage,title:ch.title,goals:ch.goals.map(g=>({...this.objective(g,port),type:g.type})),ready:ch.goals.every(g=>this.objective(g,port).ready)};};
const v4Survey=SailingGame.prototype.survey;
SailingGame.prototype.survey=function(){const s=this.s,port=s.port,keys=['day','supplies','gold','morale','knowledge'],before=Object.fromEntries(keys.map(k=>[k,s[k]])),previous=this.surveyObjectives(port);this.lastSurveyReport=null;const discoveries=v4Survey.call(this);this.lastSurveyReport={port,day:s.day,officer:s.officer,discoveries:[...discoveries],count:s.surveys[port],deltas:Object.fromEntries(keys.map(k=>[k,s[k]-before[k]])),previous,story:this.surveyObjectives(port)};return discoveries;};


