 constructor(canvas,onSelect){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.onSelect=onSelect;this.zoom=1.3;this.center=this.project([-10,31]);this.w=800;this.h=600;this.dpr=Math.min(devicePixelRatio||1,2);this.base=document.createElement('canvas');this.bc=this.base.getContext('2d');this.dirty=true;this.selected=null;this.game=null;this.drag=null;this.hover=null;this.lastTime=0;this.frame=0;this.motion=true;this.paths=COASTS.map(poly=>{const p=new Path2D();poly.forEach((pt,i)=>{const q=this.project(pt);i?p.lineTo(...q):p.moveTo(...q);});p.closePath();return p;});this.makeTextures();this.bind();new ResizeObserver(()=>this.resize()).observe(canvas.parentElement);this.resize();this.loop=this.loop.bind(this);this.raf=requestAnimationFrame(this.loop);}
