 screen(p){const q=this.project(p);return[(q[0]-this.center[0])*this.zoom+this.w/2,(q[1]-this.center[1])*this.zoom+this.h/2];}
 makeTextures(){let seed=1776;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};this.noise=document.createElement('canvas');this.noise.width=this.noise.height=160;const c=this.noise.getContext('2d');for(let i=0;i<6000;i++){const v=rnd()>.5?'255,246,210':'6,24,25';c.fillStyle=`rgba(${v},${rnd()*.045})`;c.fillRect(rnd()*160,rnd()*160,1+rnd(),1+rnd());}this.landTexture=document.createElement('canvas');this.landTexture.width=this.landTexture.height=180;const l=this.landTexture.getContext('2d');l.fillStyle='#c3b58c';l.fillRect(0,0,180,180);for(let i=0;i<9000;i++){l.fillStyle=`rgba(${rnd()>.6?'251,238,191':'77,66,36'},${rnd()*.09})`;l.fillRect(rnd()*180,rnd()*180,rnd()*2+1,rnd()*2+1);}for(let i=0;i<85;i++){l.strokeStyle='#72674715';l.beginPath();let x=rnd()*180,y=rnd()*180;l.moveTo(x,y);l.lineTo(x+6,y-4);l.stroke();}}
 resize(){const r=this.canvas.parentElement.getBoundingClientRect();if(!r.width||!r.height)return;this.w=r.width;this.h=r.height;this.canvas.width=Math.round(this.w*this.dpr);this.canvas.height=Math.round(this.h*this.dpr);this.base.width=this.canvas.width;this.base.height=this.canvas.height;this.dirty=true;}
 bind(){this.canvas.addEventListener('pointerdown',e=>{this.drag={x:e.clientX,y:e.clientY,c:[...this.center],moved:false};this.canvas.setPointerCapture(e.pointerId);document.getElementById('mapTooltip').hidden=true;});this.canvas.addEventListener('pointermove',e=>{const r=this.canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(this.drag){const dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(Math.hypot(dx,dy)>4)this.drag.moved=true;if(this.drag.moved){this.center=[this.drag.c[0]-dx/this.zoom,this.drag.c[1]-dy/this.zoom];this.constrain();this.dirty=true;}return;}const p=this.hit(x,y);this.hover=p?.id||null;this.canvas.style.cursor=p?'pointer':'grab';const tip=document.getElementById('mapTooltip');if(p){tip.innerHTML=`${p.name}<small>${p.nation} · ${this.game?.s.visited.includes(p.id)?'已发现':'尚未探索'}</small>`;tip.hidden=false;tip.style.left=Math.min(x+15,this.w-175)+'px';tip.style.top=Math.min(y+14,this.h-60)+'px';}else tip.hidden=true;});this.canvas.addEventListener('pointerup',e=>{if(this.drag&&!this.drag.moved){const r=this.canvas.getBoundingClientRect(),p=this.hit(e.clientX-r.left,e.clientY-r.top);if(p)this.onSelect(p.id);}this.drag=null;});this.canvas.addEventListener('pointercancel',()=>this.drag=null);this.canvas.addEventListener('pointerleave',()=>{this.hover=null;document.getElementById('mapTooltip').hidden=true;});this.canvas.addEventListener('wheel',e=>{e.preventDefault();const r=this.canvas.getBoundingClientRect();this.setZoom(this.zoom*(e.deltaY>0?.87:1.15),[e.clientX-r.left,e.clientY-r.top]);},{passive:false});}
 hit(x,y){let best=null,d=27;for(const p of PORTS){const q=this.screen([p.lon,p.lat]),delta=Math.hypot(q[0]-x,q[1]-y);if(delta<d){best=p;d=delta;}}return best;}
 constrain(){this.center[0]=clamp(this.center[0],150,2700);this.center[1]=clamp(this.center[1],100,1210);}
 setZoom(value,point=[this.w/2,this.h/2]){const old=this.zoom;this.zoom=clamp(value,.22,4.2);this.center[0]+=(point[0]-this.w/2)*(1/old-1/this.zoom);this.center[1]+=(point[1]-this.h/2)*(1/old-1/this.zoom);this.constrain();this.dirty=true;}
