 shipPosition(fraction=null){if(!this.game)return[-9.2,38.7];const v=this.game.s.voyage;if(!v){const p=PORT_BY_ID[this.game.s.port];return[p.lon,p.lat];}const points=v.route,lengths=points.slice(1).map((p,i)=>haversine(points[i],p)),total=lengths.reduce((a,b)=>a+b,0);let d=total*(fraction??(v.elapsed/v.total));for(let i=0;i<lengths.length;i++){if(d<=lengths[i]){const t=d/lengths[i];return[points[i][0]+(points[i+1][0]-points[i][0])*t,points[i][1]+(points[i+1][1]-points[i][1])*t];}d-=lengths[i];}return points[points.length-1];}
 worldTransform(c){c.translate(this.w/2,this.h/2);c.scale(this.zoom,this.zoom);c.translate(-this.center[0],-this.center[1]);}
 drawBase(){const c=this.bc;c.setTransform(this.dpr,0,0,this.dpr,0,0);const bg=c.createLinearGradient(0,0,this.w,this.h);bg.addColorStop(0,'#28474c');bg.addColorStop(.5,'#25434a');bg.addColorStop(1,'#1b363f');c.fillStyle=bg;c.fillRect(0,0,this.w,this.h);c.save();this.worldTransform(c);
  // 纬线、经线与旧航海图方位射线。
  c.strokeStyle='#b5c1a619';c.lineWidth=.6/this.zoom;c.setLineDash([2/this.zoom,5/this.zoom]);for(let lon=-180;lon<=180;lon+=10){const x=this.project([lon,0])[0];c.beginPath();c.moveTo(x,-100);c.lineTo(x,1500);c.stroke();}for(let lat=-60;lat<=80;lat+=10){const y=this.project([0,lat])[1];c.beginPath();c.moveTo(0,y);c.lineTo(2880,y);c.stroke();}c.setLineDash([]);
  for(const center of [[-28,25],[56,-5],[-90,25],[155,15]]){const [x,y]=this.project(center);c.strokeStyle='#a5b39316';c.lineWidth=.7/this.zoom;for(let i=0;i<16;i++){const a=i*Math.PI/8;c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.cos(a)*2000,y+Math.sin(a)*2000);c.stroke();}for(let r of [80,160,300]){c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.stroke();}}
  // 海岸浅滩与羊皮纸陆地。
  for(const path of this.paths){c.lineJoin='round';c.strokeStyle='#091f273a';c.lineWidth=17/this.zoom;c.stroke(path);c.strokeStyle='#9bbaaa24';c.lineWidth=8/this.zoom;c.stroke(path);c.fillStyle=c.createPattern(this.landTexture,'repeat');c.fill(path);c.strokeStyle='#0c2b32aa';c.lineWidth=1.5/this.zoom;c.stroke(path);c.save();c.clip(path);c.strokeStyle='#eee0aa77';c.lineWidth=3/this.zoom;c.stroke(path);c.strokeStyle='#73623c20';c.lineWidth=13/this.zoom;c.stroke(path);c.restore();}
  // 岛屿与群岛。
  for(const [lon,lat,r] of [[-17,32.6,1.7],[-16.1,28.1,2.1],[-17.6,28.7,1.2],[-15.5,27.9,1.5],[-25.7,37.7,1.8],[-27,38.5,1.3],[-28.5,38.6,1.1],[-23.5,15.2,1.5],[-24.5,16.5,1.4],[55.5,-20.8,2],[57.5,-20.3,1.8],[73.5,4.2,1.3],[120,20,1.3],[19.5,39.7,1.2]]){const q=this.project([lon,lat]);c.beginPath();c.ellipse(q[0],q[1],r*2,r,Math.PI/5,0,Math.PI*2);c.fillStyle='#c4b68b';c.fill();c.strokeStyle='#183139';c.lineWidth=1/this.zoom;c.stroke();}
  // 山脉用古地图的排线笔触绘制。
  for(const [lon,lat,n,angle] of [[-4,32,18,.15],[1,42.6,9,.05],[10,47,14,-.1],[12,43,11,1.1],[18,65,18,-1],[37,8,12,1.2],[29,-29,13,-.9],[73,33,22,.15],[99,28,17,.5],[-71,-17,28,1.5],[-114,43,24,1.1]])this.mountains(c,lon,lat,n,angle);
  // 主要河流。
  for(const points of [[[31,30],[31,26],[33,20],[32,16],[33,10]],[[17,-5],[22,-3],[25,-5],[28,-7]], [[-50,-1],[-56,-3],[-64,-3],[-70,-4]]]){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...this.project(p)):c.moveTo(...this.project(p)));c.strokeStyle='#648f8580';c.lineWidth=1;c.stroke();}
  c.restore();this.landLabel(c,'欧 罗 巴',12,53,18);this.landLabel(c,'E U R O P A',12,50,8);this.landLabel(c,'阿 非 利 加',16,14,20);this.landLabel(c,'A F R I C A',16,10,9);this.landLabel(c,'撒 哈 拉 沙 漠',8,25,10);this.landLabel(c,'亚 细 亚',82,48,22);this.landLabel(c,'A S I A',82,43,9);this.landLabel(c,'南 美 洲',-59,-16,18);this.landLabel(c,'新 世 界',-108,42,18);this.landLabel(c,'TERRA AUSTRALIS',133,-26,10);
  this.oceanLabel(c,'大 西 洋','O C E A N U S  A T L A N T I C U S',-32,21,0);this.oceanLabel(c,'印 度 洋','O C E A N U S  I N D I C U S',72,-16,-.06);this.oceanLabel(c,'太 平 洋','M A R E  P A C I F I C U M',-132,-2,-.04);this.oceanLabel(c,'地 中 海','M A R E  M E D I T E R R A N E U M',17,33,0);
  // 细微纸纹覆盖整个海图。
  c.globalAlpha=.55;c.fillStyle=c.createPattern(this.noise,'repeat');c.fillRect(0,0,this.w,this.h);c.globalAlpha=1;const vignette=c.createRadialGradient(this.w*.5,this.h*.45,50,this.w*.5,this.h*.5,Math.max(this.w,this.h)*.7);vignette.addColorStop(0,'#051c2400');vignette.addColorStop(1,'#071d2850');c.fillStyle=vignette;c.fillRect(0,0,this.w,this.h);
  this.compass(c,Math.min(108,this.w*.2),this.h-145,50);c.fillStyle='#9daf9b66';c.font='8px Georgia';c.textAlign='center';for(let lon=-180;lon<=180;lon+=10){let q=this.screen([lon,0]);if(q[0]>25&&q[0]<this.w-25)c.fillText(`${Math.abs(lon)}° ${lon<0?'W':'E'}`,q[0],this.h-5);}document.getElementById('mapScale').textContent=Math.round(63/this.zoom/8*60)+' 海里';this.dirty=false;
 }
 mountains(c,lon,lat,n,angle){const p=this.project([lon,lat]);c.save();c.translate(...p);c.rotate(angle);for(let i=0;i<n;i++){const x=(i-n/2)*4.5,y=Math.sin(i*2.5)*6,h=4+(Math.sin(i*3.6)+1)*3;c.beginPath();c.moveTo(x-4,y+3);c.lineTo(x,y-h);c.lineTo(x+5,y+3);c.strokeStyle='#70634157';c.lineWidth=.6;c.stroke();c.beginPath();c.moveTo(x,y-h);c.lineTo(x+1,y+2);c.lineTo(x+5,y+3);c.fillStyle='#7f704829';c.fill();}c.restore();}
 landLabel(c,text,lon,lat,size){const p=this.screen([lon,lat]);if(p[0]<-100||p[0]>this.w+100||p[1]<0||p[1]>this.h)return;c.save();c.fillStyle='#5c533dab';c.textAlign='center';c.font=`${Math.max(7,Math.min(size*1.2,size*this.zoom))}px "SimSun",Georgia,serif`;c.fillText(text,...p);c.restore();}
