function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.compass}</svg>`;}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function shipSVG(enemy=false){const sail=enemy?'#94856f':'#d4c9a5',light=enemy?'#b5a68b':'#efe4c2',cross=enemy?'#342b27':'#945b47';return `<svg viewBox="0 0 270 195" aria-hidden="true"><defs><linearGradient id="hull${enemy}" x2="0" y2="1"><stop stop-color="#92754b"/><stop offset="1" stop-color="#392f25"/></linearGradient></defs><g fill="none" stroke="#b4a17a" stroke-width=".65" opacity=".75"><path d="M58 144 116 19 183 148M90 151 174 43 221 144M121 19 121 151M174 39 173 148M50 123l175 13M67 109l109-19M79 97l97-7M44 152 123 46 198 153M75 156l48-137m26 137L123 19m44 138 7-117m29 115-29-115"/></g><path d="m30 147 29 7 144-5 31-11-17 31-128 10-31-11Z" fill="url(#hull${enemy})" stroke="#bda775" stroke-width="1.2"/><path d="m40 155 46 13 128-11M65 164l29 10 117-9" fill="none" stroke="#aa8c55" stroke-width=".8"/><path d="M62 151v-16l28 4 4 15m100-4 1-19 31-4-5 18" fill="#765a38" stroke="#b9a178" stroke-width="1"/><path d="M65 139 91 143m106-7 24-4" stroke="#d4bb81" fill="none"/><g fill="#14272b" stroke="#b69a65" stroke-width=".7"><path d="m89 158 6 1v5l-6-1Zm15 0h6v5h-6Zm15-1h6v5h-6Zm15-1h6v5h-6Zm15-1h6v5h-6Zm15-1h6v5h-6Zm15-1h6v5h-6Z"/></g><path d="M122 15v143m52-121v115M78 66v83" stroke="#ad9360" stroke-width="2.5"/><path d="M80 87h72M76 45h77M137 67h68M145 112h55M52 105h41" stroke="#8e784d" stroke-width="2"/><path d="M83 48Q91 65 80 83Q121 92 150 82Q139 65 147 48Z" fill="${light}" stroke="#a09270" stroke-width=".8"/><path d="M81 91Q83 118 67 132Q111 149 156 130Q141 111 151 91Z" fill="${sail}" stroke="#a09270" stroke-width=".8"/><path d="M144 70Q150 90 140 105Q168 115 201 106Q192 88 201 70Z" fill="${sail}" stroke="#a09270" stroke-width=".8"/><path d="M151 116Q150 132 144 141Q169 147 194 138L197 116Z" fill="${light}" stroke="#a09270" stroke-width=".8"/><path d="M77 67 44 119l31 10Z" fill="${light}" stroke="#a09270" stroke-width=".8"/><path d="M203 90 228 132 204 136Z" fill="${light}" stroke="#a09270" stroke-width=".8"/><g fill="none" stroke="#938465" stroke-width=".55" opacity=".6"><path d="M97 49q7 19-1 35m16-35q8 20 0 37m15-37q9 20 4 36M94 94q5 26-6 44m20-45q6 26 0 49m17-48q6 25 1 45m14-44q0 24 4 39M158 72q5 18-1 36m18-36q4 20 0 36"/></g><g fill="${cross}"><path d="M111 54h8v24h-8Zm-8 8h24v8h-24M163 77h6v24h-6Zm-6 8h18v6h-18"/></g><path d="M123 16q15-10 30 0-13-2-18 5l-12-2Z" fill="${enemy?'#292827':'#b38a43'}"/><path d="M175 39q11-7 22 0l-22 4Z" fill="#a7614b"/><path d="m30 146-12-14 35 9M224 137l26-16" stroke="#bba070" stroke-width="2"/><path d="M36 180q49 10 100 0t105-6M62 187q45 6 80-1t71-4" fill="none" stroke="#8dab9e" stroke-width=".7" opacity=".4"/></svg>`;}
const $=id=>document.getElementById(id),escapeHTML=str=>String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('en-US');
const dateAt=day=>new Date(Date.UTC(1500,5,1+day));
const dateText=day=>{const d=dateAt(day);return`${d.getUTCFullYear()} 年 ${d.getUTCMonth()+1} 月 ${d.getUTCDate()} 日`;};
const shortDate=day=>{const d=dateAt(day);return`${d.getUTCMonth()+1}.${String(d.getUTCDate()).padStart(2,'0')} / ${d.getUTCFullYear()}`;};
let gameplayActive=false,tickRAF=null;
let game,chart,selected=null,currentModal=null,modalLocked=false,resumeAfterModal=false,focusBeforeModal=null,battle=null,storageOK=true,lastTick=0,sound=null,importCandidate=null;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('toasts').append(el);setTimeout(()=>el.remove(),4500);}
function saveGame(notify=false){if(!gameplayActive||!game)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(game.s));storageOK=true;if(notify)toast('航程已保存。下次打开会从这里继续。');}catch{storageOK=false;if(notify)toast('浏览器暂不允许本地保存，请在设置中导出存档。',true);}}
function loadGame(){const raw=localStorage.getItem(SAVE_KEY);return raw?validateSave(JSON.parse(raw)):newState();}
function safe(action){try{const result=action();saveGame();render();return result;}catch(e){toast(e.message,true);if(sound)sound.fx('error');return null;}}
function rank(){return game.s.fame>=130?'七海的传奇':game.s.fame>=80?'受人敬仰的大航海家':game.s.fame>=40?'声名远扬的船长':game.s.fame>=15?'崭露头角的探险家':'初出茅庐的航海家';}
function render(){const s=game.s,p=PORT_BY_ID[s.port];$('gold').textContent=fmt(s.gold);$('supplies').innerHTML=`${s.supplies} <em>/ ${game.maxSupplies}</em>`;$('crew').innerHTML=`${s.crew} <em>/ ${s.morale}%</em>`;$('fame').textContent=s.fame;$('portName').textContent=p.name;$('portEnglish').textContent=p.en;$('portNation').textContent=p.nation;$('portDescription').textContent=p.desc;$('portSpecial').textContent=p.special;$('portCoordinate').textContent=`${Math.abs(p.lat).toFixed(1)}° ${p.lat>0?'N':'S'} · ${Math.abs(p.lon).toFixed(1)}° ${p.lon>0?'E':'W'}`;$('supplyCost').textContent=fmt((game.maxSupplies-s.supplies)*3)+' G';$('supplyButton').disabled=!!s.voyage||s.supplies===game.maxSupplies;$('gameDate').textContent=dateText(s.day);$('dayCount').textContent=`旅程第 ${s.day+1} 天`;const m=dateAt(s.day).getUTCMonth();$('season').textContent=['冬 · 留意风暴','冬 · 留意风暴','春 · 新航季','春 · 新航季','春 · 新航季','夏 · 顺风时节','夏 · 顺风时节','夏 · 顺风时节','秋 · 贸易旺季','秋 · 贸易旺季','秋 · 贸易旺季','冬 · 留意风暴'][m];$('weatherText').textContent=s.voyage?'季风稳定 · 保持航向':'东北风 · 风平浪静';$('hullLabel').textContent=`${s.hull} / ${game.maxHull}`;$('hullBar').style.width=s.hull/game.maxHull*100+'%';$('hullBar').style.background=s.hull<30?'#c98570':'';$('cargoLabel').textContent=`${game.cargoCount} / ${game.capacity}`;$('cargoBar').style.width=game.cargoCount/game.capacity*100+'%';$('shipSpeed').textContent=game.speed.toFixed(1);$('shipGuns').textContent=game.guns;$('captainRank').textContent=rank();$('discoveryCount').textContent=`已发现 ${s.visited.length} / ${PORTS.length} 港口`;$('seaLocation').textContent=s.voyage?'航向 '+PORT_BY_ID[s.voyage.to].name:p.region+' · '+(s.voyage?'公海':'沿岸海域');$('tutorial').hidden=!s.tutorial||!!s.voyage;$('statusMessage').textContent=s.voyage?'航行中 · 空格暂停 / 继续 · 可在地图上自由探索':'拖动探索海图 · 滚轮缩放 · 空格暂停航行';document.querySelector('.port-panel>.section-label').innerHTML=`<span>${s.voyage?'最近离港':'当前停泊港'}</span><span class="live-dot">${s.voyage?'海上':'港内'}</span>`;document.querySelector('.right-footer .live-dot').textContent=storageOK?'自动记录航程':'请导出存档以保留进度';
 const q=QUESTS.find(q=>!s.claimed.includes(q.id));$('nextQuest').innerHTML=q?`<h4>${q.title}</h4><p>${q.desc}</p><div class="quest-reward">${fmt(q.reward)} G <span>+ ${q.fame} 声望</span></div>${q.test(s)?`<button class="small-button" style="margin-top:12px;width:100%" data-claim="${q.id}">委托已达成 · 领取奖励</button>`:''}`:'<h4>传奇仍在继续</h4><p>所有委托已完成。世界的每一片海，都等待着你的船帆。</p>';$('recentLogs').innerHTML=s.logs.slice(0,3).map(l=>`<div class="mini-log"><small>${shortDate(l.day)}</small>${escapeHTML(l.text)}</div>`).join('');chart.game=game;chart.selected=selected;chart.motion=s.settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches;document.body.classList.toggle('no-motion',!s.settings.motion);renderRoute();icons(document);updateVoyage();}
function renderRoute(){const s=game.s;$('routeFrom').textContent=PORT_BY_ID[s.port].name;const to=s.voyage?.to||selected;let e=null;if(to&&to!==s.port)e=s.voyage?{days:s.voyage.total,supplies:s.voyage.total*s.voyage.supplyPerDay,distance:s.voyage.distance}:game.estimate(to);$('routeTo').textContent=to?PORT_BY_ID[to].name:'驶向未知';$('routeRegion').textContent=to?PORT_BY_ID[to].region:'选择目的地';$('routeDays').innerHTML=e?`${e.days}<em> 天</em>`:'—<em> 天</em>';$('routeSupply').innerHTML=e?`${e.supplies}<em> 单位</em>`:'—<em> 单位</em>';$('routeHint').textContent=s.voyage?`全程 ${fmt(e.distance)} 海里 · 船员正在按既定航线航行`:e?`${fmt(e.distance)} 海里 · ${s.visited.includes(to)?'熟悉的贸易航路':'尚未探索的港口'}${e.supplies>s.supplies?' · 补给不足':''}`:'点击港口，或从港口索引中选择目的地';$('sailButton').disabled=!!s.voyage||!e;$('sailButton').querySelector('span').textContent=s.voyage?'远航中':'扬帆起航';}
function updateVoyage(){const v=game.s.voyage;$('voyageBanner').hidden=!v;if(!v)return;$('voyageTitle').textContent=`${PORT_BY_ID[v.from].name} → ${PORT_BY_ID[v.to].name}`;$('voyageProgress').style.width=v.elapsed/v.total*100+'%';$('voyageStatus').textContent=`航行第 ${v.elapsed} / ${v.total} 天 · 剩余补给 ${game.s.supplies} · ${v.paused?'已暂停':'预计 '+(v.total-v.elapsed)+' 天后抵达'}`;$('pauseVoyage').textContent=v.paused?'继续':'暂停';$('speedVoyage').textContent=game.s.settings.speed+'×';}
function selectPort(id){if(!PORT_BY_ID[id])return;if(game.s.voyage){toast('当前航程中，抵港后可规划下一段路线。');return;}if(id===game.s.port){showPort();return;}selected=id;game.s.tutorial=false;chart.selected=id;render();if(sound)sound.fx('click');}
function openModal(title,eyebrow,body,type,locked=false){if(!currentModal){focusBeforeModal=document.activeElement;resumeAfterModal=!!game.s.voyage&&!game.s.voyage.paused;if(game.s.voyage)game.s.voyage.paused=true;}$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=body;$('modalOverlay').hidden=false;currentModal=type;modalLocked=locked;$('closeModal').hidden=locked;$('modal').classList.toggle('locked',locked);$('modalBody').scrollTop=0;icons($('modal'));updateVoyage();requestAnimationFrame(()=>{const focusable=$('modal').querySelector('button:not([hidden]):not(:disabled),input');focusable?.focus({preventScroll:true});});}
function replaceBody(body){$('modalBody').innerHTML=body;icons($('modalBody'));}
function closeModal(force=false){if(modalLocked&&!force)return;$('modalOverlay').hidden=true;currentModal=null;modalLocked=false;if(game.s.voyage&&resumeAfterModal){game.s.voyage.paused=false;lastTick=performance.now();}resumeAfterModal=false;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view==='map'));focusBeforeModal?.focus?.({preventScroll:true});updateVoyage();saveGame();}
function markNav(view){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function marketHTML(){const s=game.s,p=PORT_BY_ID[s.port],list=GOODS.filter(g=>p.market.includes(g.id)||s.cargo[g.id]);return`<p class="modal-subtitle">${s.voyage?'海上只可查看货舱；抵港后即可交易。':'货物以「箱」计量。特产产地价格更低，远方的港口往往愿意支付更高的价格。'}</p><div class="modal-toolbar"><div class="wallet"><small>可用金币</small>${fmt(s.gold)} <small>G</small></div><span class="chip">货舱 ${game.cargoCount} / ${game.capacity} 箱</span></div><div class="table-wrap"><table class="market-table"><thead><tr><th>货物</th><th>买入 / 卖出</th><th>持有</th><th>交易数量</th></tr></thead><tbody>${list.map(g=>{const pz=game.price(g.id),held=s.cargo[g.id]?.qty||0,supplied=p.market.includes(g.id);return`<tr><td><div class="good-cell"><i>${icon(g.icon)}</i><div>${g.name}<small>${g.origin.includes(s.port)?'◆ 本港特产':held?'成本 '+Math.round(s.cargo[g.id].cost/held)+' G / 箱':g.desc}</small></div></div></td><td class="price-cell">${supplied?pz.buy:'—'} <span style="color:#859b90">/ ${pz.sell}</span><small class="${pz.trend>15?'expensive':''}">${pz.trend<0?'↓ 低于':'↑ 高于'}基准 ${Math.abs(pz.trend)}%</small></td><td>${held}<small style="display:block;color:#81978c;font-size:9px;margin-top:5px">箱</small></td><td><div class="trade-actions"><input class="qty-input" aria-label="${g.name}交易数量" id="qty-${g.id}" type="number" min="1" max="10000" value="1" step="1"><button class="small-button" data-buy="${g.id}" ${!supplied||s.voyage?'disabled':''}>买入</button><button class="small-button sell" data-sell="${g.id}" ${!held||s.voyage?'disabled':''}>卖出</button></div></td></tr>`;}).join('')}</tbody></table></div><p class="market-foot">卖价已扣除交易税费。行情每 7 天变动；再次买入同种货物会按加权平均成本记录利润。<br>推荐初航：在里斯本装载葡萄酒，运往埃尔米纳；或前往马德拉购入砂糖，带回欧洲。</p>`;}
function showTrade(){openModal(PORT_BY_ID[game.s.port].name+' · 交易所','MERCHANT EXCHANGE',marketHTML(),'trade');markNav('trade');}
function fleetHTML(){const s=game.s,cost=(game.maxHull-s.hull)*5;return`<div class="fleet-summary">${shipSVG()}<div><h3>圣加布里埃尔号</h3><p>轻型卡拉维尔帆船 · ${rank()}<br>一艘灵巧可靠的远洋帆船，陪伴你从家乡驶向七海。</p><div class="fleet-values"><span><b>${game.speed.toFixed(1)} 节</b>当前航速</span><span><b>${game.guns} 门</b>舰载火炮</span><span><b>${s.crew} 人</b>在役船员</span></div></div></div><div class="service-row" style="padding-top:0;margin-bottom:20px"><div><strong>船体耐久 ${s.hull} / ${game.maxHull}</strong><p>维修每点耐久消耗 5 金币。航行前请保持船况良好。</p></div><button class="small-button" data-action="repair" ${!cost||s.voyage?'disabled':''}>${cost?'完全修理 · '+fmt(cost)+' G':'船体完好'}</button></div><div class="upgrade-grid">${UPGRADES.map(u=>{const level=s.upgrades[u.id],maxed=level===u.max;return`<div class="upgrade-card"><i>${icon(u.icon)}</i><div><h4>${u.name}</h4><p>${u.desc}</p><div class="level-dots">${Array.from({length:u.max},(_,i)=>`<b class="${i<level?'filled':''}"></b>`).join('')}</div><button class="small-button" data-upgrade="${u.id}" ${maxed||s.voyage?'disabled':''}>${maxed?'已完成全部改装':`改装至 ${level+1} 级 · ${fmt(u.base*(level+1))} G`}</button></div></div>`;}).join('')}</div><p class="market-foot">货舱与粮仓独立计算。满载略微降低航速；低于 18 名船员或低士气也会影响航速。升级帆装能减少远洋航行的补给消耗。</p>`;}
function showFleet(){openModal('舰队与造船厂','YOUR FLAGSHIP',fleetHTML(),'fleet');markNav('fleet');}
function tavernHTML(){const s=game.s,p=PORT_BY_ID[s.port];return`<div class="tavern-quote">${p.rumor}<small>— ${p.name}酒馆里，一位老水手的忠告</small></div><div class="service-row"><div><strong>请船员畅饮</strong><p>士气 +25 · 消耗 1 天 · 当前士气 ${s.morale}%</p></div><button class="small-button" data-action="feast" ${s.morale>=100?'disabled':''}>180 G · 举杯</button></div><div class="service-row"><div><strong>招募熟练水手</strong><p>招募 6 人 · 当前 ${s.crew} / 60 人<br>每 12 名船员每天消耗 1 单位补给；更多船员有利于接舷战。</p></div><button class="small-button" data-action="recruit" ${s.crew>=60?'disabled':''}>240 G · 招募</button></div><div class="service-row"><div><strong>码头临时工作</strong><p>协助装卸 2 天，获得 420 金币与 24 单位补给。</p></div><button class="small-button sell" data-action="work">接受工作</button></div><div class="service-row"><div><strong>港外海盗悬赏</strong><p>迎击海盗，胜利可获得金币与声望。<br>有真实战损，请先修好你的船。</p></div><button class="small-button danger" data-action="hunt">出港迎击</button></div>`;}
function showTavern(){if(game.s.voyage){toast('酒馆在港口等候你的归来。',true);return;}openModal(PORT_BY_ID[game.s.port].name+' · 水手酒馆','THE SAILOR’S REST',tavernHTML(),'tavern');}
function questsHTML(){const s=game.s;return`<p class="modal-subtitle">海事公会记录你的每一次探索。完成条件后，请在港口领取奖励；所有货物仍归你所有。</p><div class="quest-list">${QUESTS.map((q,i)=>{const done=s.claimed.includes(q.id),ready=q.test(s),progress=Math.min(q.total,q.progress(s));return`<div class="quest-item ${done?'done':''}"><div class="quest-number">${String(i+1).padStart(2,'0')}</div><div><h3>${q.title}</h3><p>${q.desc}</p><div class="meter gold-meter"><span style="width:${done?100:progress/q.total*100}%"></span></div><div class="quest-reward">${fmt(q.reward)} G <span>+ ${q.fame} 声望</span></div></div><div style="text-align:right"><span class="chip">${done?'已完成':ready?'可领取':`${fmt(progress)} / ${fmt(q.total)}`}</span><br><button class="small-button" data-claim="${q.id}" ${done||!ready||s.voyage?'disabled':''}>${done?'荣誉已记录':'领取奖励'}</button></div></div>`;}).join('')}</div>`;}
function showQuests(){openModal('写下你的航海传奇','MARITIME COMMISSIONS',questsHTML(),'quests');markNav('quests');}
function showJournal(){const s=game.s;openModal('船长的航海日志','THE CAPTAIN’S JOURNAL',`<div class="summary-stats"><div><strong>${fmt(s.distance)}</strong><span>累计航行 / 海里</span></div><div><strong>${s.visited.length}</strong><span>发现港口</span></div><div><strong>${fmt(s.profit)}</strong><span>贸易净利润 / G</span></div></div><div class="journal-list">${s.logs.map(l=>`<div class="journal-entry"><small>${dateText(l.day)}</small><p>${escapeHTML(l.text)}</p></div>`).join('')}</div>`,'journal');markNav('journal');}
function portListHTML(filter=''){return PORTS.filter(p=>(p.name+p.en+p.region+p.nation).toLowerCase().includes(filter.toLowerCase())).map(p=>{const v=game.s.visited.includes(p.id);let days=p.id===game.s.port?0:game.estimate(p.id).days;return`<button class="port-index-item" data-port="${p.id}"><strong>${p.name}</strong><small>${p.region} · ${p.nation}</small><em>${p.id===game.s.port?'当前停泊':`预计 ${days} 天航程 · ${p.special}`}</em>${v?'<span class="visited-tag">◆</span>':''}</button>`;}).join('')||'<p class="empty-state">这片海域里没有匹配的港口。</p>';}
function showPorts(){openModal('选择下一座港口','PORTS OF THE KNOWN WORLD',`<input id="portSearch" class="port-search" type="search" placeholder="搜索港口、国家或海域…" aria-label="搜索港口"><div class="port-grid" id="portGrid">${portListHTML()}</div>`,'ports');}
function showPort(){const p=PORT_BY_ID[game.s.port];openModal(p.name+' · 港口服务','WELCOME ASHORE',`<p class="modal-subtitle">${p.desc}</p><div class="service-row"><div><strong>组织考察</strong><p>近岸观察、学识与城市篇章进度</p></div><button class="small-button" data-action="survey">前往考察</button></div><div class="service-row"><div><strong>城市篇章</strong><p>当地接取与提交委托</p></div><button class="small-button" data-action="local-story">聆听故事</button></div><div class="service-row"><div><strong>交易所</strong><p>本港特产：${p.special}</p></div><button class="small-button" data-action="trade">进入交易所</button></div><div class="service-row"><div><strong>造船厂</strong><p>维修、扩舱、改良帆装和火炮</p></div><button class="small-button" data-action="fleet">进入造船厂</button></div><div class="service-row"><div><strong>水手酒馆</strong><p>招募、畅饮、工作与海盗悬赏</p></div><button class="small-button" data-action="tavern">进入酒馆</button></div><div class="service-row"><div><strong>补满航海物资</strong><p>当前 ${game.s.supplies} / ${game.maxSupplies} · 每单位 3 G</p></div><button class="small-button" data-action="refill">${fmt((game.maxSupplies-game.s.supplies)*3)} G · 补满</button></div>`,'port');}
function showHelp(){openModal('每一位传奇，都曾第一次出海','THE NAVIGATOR’S HANDBOOK',`<div class="help-grid"><div class="help-card"><h3>${icon('compass')} 01 · 规划航程</h3><p>点击海图上的港口，或打开右上角「港口索引」。选定目的地后，底部会显示天数与补给消耗。点击「扬帆起航」出发。</p></div><div class="help-card"><h3>${icon('trade')} 02 · 做成第一笔生意</h3><p>前往交易所，输入数量后买卖货物。产地特产更便宜：马德拉的砂糖、埃尔米纳的黄金与印度的胡椒，都是值得留意的商品。</p></div><div class="help-card"><h3>${icon('ship')} 03 · 照顾好你的船</h3><p>船员每天消耗补给并领取工资。抵港可补满物资、修复船体。扩充粮仓、改良帆装有助远洋；更强的火炮有助海战。</p></div><div class="help-card"><h3>${icon('battle')} 04 · 应对海上遭遇</h3><p>航程中的事件会暂停时间。在海战中，瞄准指针靠近中央绿色区时开炮，准确度最高；链弹削弱敌方火力，接舷适合低耐久敌船。</p></div></div><p class="help-tip">推荐开局：在里斯本买入 20 箱葡萄酒 → 补满物资 → 抵达马德拉并领取首航奖励 → 尝试贸易，逐渐向西非推进。<br>快捷操作：拖动地图 / 滚轮缩放；空格暂停或继续航行；Esc 关闭普通窗口。手机端可通过当前港口标记进入港口服务。<br>游戏自动保存，也可以在设置中导出存档。若资金不足，酒馆的码头工作可帮你重新起航。</p><p class="market-foot">本作是致敬经典航海游戏的原创单人沙盒，使用原创界面、程序化海图和专门生成的港口画作。港口开放年代与商业环境经过游戏化处理。</p>`,'help');}
function settingsHTML(){return`<div class="settings-row"><div><strong>航行速度</strong><p>仅加快现实等待时间，不改变游戏天数与资源消耗。</p></div><select id="speedSetting" aria-label="航行速度"><option value="1" ${game.s.settings.speed===1?'selected':''}>悠然航行 · 1×</option><option value="2" ${game.s.settings.speed===2?'selected':''}>乘风破浪 · 2×</option><option value="4" ${game.s.settings.speed===4?'selected':''}>疾速远航 · 4×</option></select></div><div class="settings-row"><div><strong>海图动态效果</strong><p>控制海流、船只起伏与航线动画。</p></div><button class="small-button" data-action="motion">${game.s.settings.motion?'已开启 · 点击关闭':'已关闭 · 点击开启'}</button></div><div class="settings-row"><div><strong>保存与迁移</strong><p>自动保存在当前浏览器。导出文件可跨设备恢复。</p></div><div style="display:flex;gap:7px"><button class="small-button" data-action="export">导出存档</button><button class="small-button" data-action="import">导入</button></div></div><div class="settings-row"><div><strong>开启新航程</strong><p>重置金币、船只和探索记录。建议先导出存档。</p></div><button class="small-button danger" data-action="reset">重新开始</button></div><p class="market-foot">完全离线 · 无外部依赖 · 无需登录<br>七海编年史 v2.0 / CHRONICLES OF THE SEVEN SEAS</p>`;}
function showSettings(){openModal('船长偏好','CAPTAIN’S PREFERENCES',settingsHTML(),'settings');}
function exportSave(){const blob=new Blob([JSON.stringify(game.s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`风与黄金-第${game.s.day+1}天.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出。保留 JSON 文件即可恢复航程。');}
function refreshCurrent(){if(currentModal==='trade')replaceBody(marketHTML());if(currentModal==='fleet')replaceBody(fleetHTML());if(currentModal==='tavern')replaceBody(tavernHTML());if(currentModal==='quests')replaceBody(questsHTML());if(currentModal==='settings')replaceBody(settingsHTML());if(currentModal==='port')showPort();}
function beginVoyage(){const result=safe(()=>game.depart(selected));if(!result)return;game.s.tutorial=false;chart.selected=selected;chart.locate();lastTick=performance.now();saveGame();render();if(sound)sound.fx('depart');toast(`已扬帆！目标${PORT_BY_ID[selected].name}，预计 ${result.days} 天抵达。`);}
function togglePause(){if(!game.s.voyage||modalLocked||currentModal)return;game.s.voyage.paused=!game.s.voyage.paused;lastTick=performance.now();updateVoyage();saveGame();}
function tickLoop(t){tickRAF=null;if(!gameplayActive||document.hidden)return;if(game.s.voyage&&!game.s.voyage.paused&&!currentModal&&t-lastTick>1100/game.s.settings.speed){lastTick=t;const result=game.tick();render();saveGame();if(result.type==='event')showEvent(result.event);else if(result.type==='arrival'){selected=null;chart.selected=null;chart.locate();render();if(sound)sound.fx('arrival');toast(`${result.isNew?'发现新港口':'平安抵达'} · ${PORT_BY_ID[result.port].name}`);const q=QUESTS.find(q=>!game.s.claimed.includes(q.id)&&q.test(game.s));if(q)setTimeout(()=>toast(`委托「${q.title}」已达成，可领取 ${fmt(q.reward)} G。`),1200);}else if(result.type==='rescue')showRescue();}tickRAF=requestAnimationFrame(tickLoop);}
function finishEvent(message){if(message){game.log(message);toast(message);}closeModal(true);if(game.s.voyage)game.s.voyage.paused=false;lastTick=performance.now();saveGame();render();}
function showEvent(type){const events={
 storm:{title:'乌云压低了海平线',sub:'A STORM ON THE HORIZON',copy:'风向突然变了。远方的乌云像山峦一样逼近，甲板上的绳索绷紧，老水手等待你的命令。',note:'收帆可减少船损，但会额外耗费 2 天航程；强行穿越可能损伤船体。',buttons:[['storm-safe','收帆避风','secondary'],['storm-risk','迎风穿越','primary']]},
 wreck:{title:'海面上的漂流船',sub:'A SILENT SHIP',copy:'一艘失去桅杆的商船在浪间漂浮。船尾仍系着几只完好的货箱，也许值得派一队水手前往。',note:'登船搜索可能找到金币与补给，也可能被破损的船体所伤。',buttons:[['wreck-search','派人登船','primary'],['event-pass','继续航行','secondary']]},
 dolphins:{title:'与海豚同行',sub:'COMPANIONS OF THE SEA',copy:'一群海豚跃出船首的浪花，像银色的箭。船员们涌向舷边，久违的笑声盖过了风声。',note:'这片辽阔的海，偶尔也会温柔地款待远行之人。船员士气将提升 12。',buttons:[['dolphins','追随风与海','primary']]},
 merchant:{title:'擦肩而过的商船',sub:'A FRIENDLY SAIL',copy:'一面友善的旗帜从远方升起。商船船长愿意出售备用食水，并分享这片海域的消息。',note:'200 金币购买最多 60 单位补给；多余物资受粮仓容量限制。',buttons:[['merchant-buy','交换物资 · 200 G','primary'],['event-pass','挥手致意','secondary']]},
 pirate:{title:'黑帆出现在地平线上',sub:'BLACK SAILS APPROACH',copy:'瞭望手的呼喊划破平静。几艘不明船只正向你逼近，黑色旗帜下闪过火炮的寒光。',note:'备战迎敌可夺取战利品；支付 350 金币通行费，也可以避开这场战斗。',buttons:[['pirate-fight','全员战斗准备','primary'],['pirate-pay','交涉 · 350 G','secondary']]}
 };const e=events[type];openModal(e.title,e.sub,`<div class="event-art ${type==='storm'?'storm':''}">${shipSVG(type==='pirate')}</div><p class="event-copy">${e.copy}</p><p class="event-note">${e.note}</p><div class="event-actions">${e.buttons.map(([action,title,cls])=>`<button class="${cls}" data-event="${action}">${title}</button>`).join('')}</div>`,'event',true);if(sound)sound.fx(type==='pirate'?'danger':'event');}
function resolveEvent(action){if(currentModal!=='event')return;const s=game.s;if(action==='pirate-fight'){startBattle(false);return;}if(action==='pirate-pay'){if(s.gold<350){toast('金币不足，准备战斗后仍可尝试撤退。',true);return;}s.gold-=350;finishEvent('交涉成功。支付 350 金币后，黑帆消失在视野里。');return;}if(action==='storm-safe'){if(s.voyage)s.voyage.total+=2;s.hull=Math.max(1,s.hull-3);finishEvent('收帆避过风暴。航程延长 2 天，船体受到 3 点轻伤。');return;}if(action==='storm-risk'){const damage=Math.round(10+game.rand()*22);s.hull=Math.max(0,s.hull-damage);if(s.hull===0){game.rescue();closeModal(true);showRescue();return;}finishEvent(`圣加布里埃尔号冲破巨浪，船体损伤 ${damage} 点。`);return;}if(action==='wreck-search'){if(game.rand()<.77){const gold=Math.round(240+game.rand()*550),supply=Math.min(25,game.maxSupplies-s.supplies);s.gold+=gold;s.supplies+=supply;finishEvent(`找到 ${gold} 金币与 ${supply} 单位补给。海洋归还了一小部分秘密。`);}else{s.hull=Math.max(1,s.hull-12);finishEvent('漂流船突然倾覆。水手及时返回，船体擦伤 12 点。');}return;}if(action==='dolphins'){s.morale=Math.min(100,s.morale+12);finishEvent('海豚伴船而行。船员士气提升 12。');return;}if(action==='merchant-buy'){if(s.gold<200){toast('金币不足。',true);return;}if(s.supplies>=game.maxSupplies){toast('粮仓已满，无需交易。',true);return;}const n=Math.min(60,game.maxSupplies-s.supplies);s.gold-=200;s.supplies+=n;finishEvent(`与商船交换 ${n} 单位食水，支付 200 金币。`);return;}finishEvent('向远方的船帆致意，继续既定航程。');}
function startBattle(hunt){if(hunt){try{game.checkPort();if(game.s.hull<40)throw new Error('船体耐久至少 40，才能主动出港迎击。');}catch(e){toast(e.message,true);return;}game.s.day++;}const tier=Math.min(3,Math.floor(game.s.fame/45)),hp=75+tier*20;battle={hp,maxHp:hp,turn:0,slow:0,busy:false,hunt,seed:performance.now(),log:'敌舰正在接近。等瞄准指针靠近中央，再下令齐射。',reward:Math.round(650+game.rand()*500+tier*150),tier};openModal('炮声响彻海面','NAVAL ENGAGEMENT',battleHTML(),'battle',true);if(sound)sound.fx('danger');requestAnimationFrame(battleFrame);}
function battleHTML(){return`<div class="battle-header-note">圣加布里埃尔号 vs 黑鸦号 · ${game.guns} 门火炮 · ${game.s.crew} 名船员</div><div class="battle-scene"><div class="battle-ship player" id="playerBattleShip">${shipSVG()}</div><div class="battle-vs">VS</div><div class="battle-ship enemy" id="enemyBattleShip">${shipSVG(true)}</div><div class="battle-bars"><div>圣加布里埃尔号 <strong id="battlePlayerHP">${game.s.hull} / ${game.maxHull}</strong><div class="meter"><span id="battlePlayerBar" style="width:${game.s.hull/game.maxHull*100}%"></span></div></div><div>黑鸦号 <strong id="battleEnemyHP">${battle.hp} / ${battle.maxHp}</strong><div class="meter"><span id="battleEnemyBar" class="enemy-meter" style="width:${battle.hp/battle.maxHp*100}%"></span></div></div></div></div><div class="aim-label"><span>齐射瞄准 · 中央绿色区域伤害更高</span><span id="battleTurn">第 1 回合</span></div><div class="aim-track"><span class="aim-marker" id="aimMarker"></span></div><div class="battle-actions"><button data-combat="fire">火炮齐射<small>瞄准 · 主要伤害</small></button><button data-combat="chain">链弹断帆<small>降低敌舰反击</small></button><button data-combat="board">接舷突击<small>敌耐久 ≤ 35% 更佳</small></button><button data-combat="flee">全速脱离<small>尝试撤离战场</small></button></div><div class="battle-log" id="battleLog">${battle.log}</div>`;}
function aimValue(){return .5+Math.sin((performance.now()-battle.seed)/610)*.48;}
function battleFrame(){if(!battle||currentModal!=='battle')return;const marker=$('aimMarker');if(marker)marker.style.left=(game.s.settings.motion?aimValue()*100:50)+'%';requestAnimationFrame(battleFrame);}
function updateBattle(){if(!battle)return;$('battlePlayerHP').textContent=`${game.s.hull} / ${game.maxHull}`;$('battleEnemyHP').textContent=`${battle.hp} / ${battle.maxHp}`;$('battlePlayerBar').style.width=game.s.hull/game.maxHull*100+'%';$('battleEnemyBar').style.width=battle.hp/battle.maxHp*100+'%';$('battleLog').textContent=battle.log;$('battleTurn').textContent=`第 ${battle.turn+1} 回合`;$('modalBody').querySelectorAll('[data-combat]').forEach(b=>b.disabled=battle.busy);render();}
function combat(action){if(!battle||battle.busy||currentModal!=='battle')return;const b=battle,s=game.s;b.busy=true;b.turn++;let damage=0,report='';if(action==='flee'){if(game.rand()<clamp(.56+s.upgrades.sails*.12+b.slow*.12,.1,.95)){finishBattle('fled');return;}report='脱离失败，敌舰紧追不舍。';}else if(action==='board'){const chance=b.hp/b.maxHp<=.35?.82:clamp(.13+(s.crew-24)*.012,.08,.55);if(game.rand()<chance){finishBattle('won');return;}report='敌方守住了舷梯，突击未能得手。';s.morale=Math.max(0,s.morale-5);}else{const accuracy=game.s.settings.motion?1-Math.abs(aimValue()-.5)*1.6:1;damage=Math.round((action==='chain'?10+(game.guns-8)/8*4:19+(game.guns-8)/8*9)*(accuracy+.15+game.rand()*.2));b.hp=Math.max(0,b.hp-damage);if(action==='chain')b.slow=Math.min(3,b.slow+1);report=action==='chain'?`链弹撕裂敌帆，造成 ${damage} 点伤害，敌方反击减弱。`:`${accuracy>.86?'精准齐射！':'火炮齐射，'}造成 ${damage} 点伤害。`;$('enemyBattleShip')?.classList.add('hit');if(sound)sound.fx('cannon');}b.log=report;updateBattle();if(b.hp<=0){setTimeout(()=>finishBattle('won'),600);return;}setTimeout(()=>{if(battle!==b)return;const retaliation=Math.max(3,Math.round((9+game.rand()*10+b.tier*3)*(1-b.slow*.18)));s.hull=Math.max(0,s.hull-retaliation);b.log+=` 敌舰还击，船体损伤 ${retaliation} 点。`;$('playerBattleShip')?.classList.add('hit');$('enemyBattleShip')?.classList.remove('hit');if(sound)sound.fx('hit');b.busy=false;updateBattle();saveGame();setTimeout(()=>$('playerBattleShip')?.classList.remove('hit'),350);if(s.hull<=0)finishBattle('lost');},700);}
function finishBattle(result){if(!battle)return;const b=battle;battle=null;const s=game.s;if(result==='lost'){game.rescue();closeModal(true);showRescue();return;}if(result==='fled'){s.morale=Math.max(0,s.morale-5);finishEvent('利用风向甩开敌舰，成功脱离战场。士气下降 5。');return;}s.gold+=b.reward;s.fame+=8;s.battles++;s.morale=Math.min(100,s.morale+10);game.log(`击败黑鸦号，获得 ${b.reward} 金币战利品与 8 声望。`,'quest');openModal('胜利属于勇敢的船长','VICTORY AT SEA',`<div class="win-seal">${icon('battle')}</div><h3 class="win-title">凯旋</h3><p class="modal-subtitle" style="text-align:center">黑帆落下，海面重归平静。船员们高呼着你的名字。</p><div class="summary-stats"><div><strong>+ ${fmt(b.reward)}</strong><span>战利品 / G</span></div><div><strong>+ 8</strong><span>航海声望</span></div><div><strong>${s.hull}</strong><span>剩余船体耐久</span></div></div><button class="primary" style="width:100%" data-action="battle-continue">${s.voyage?'整理甲板，继续航行':'返回港口'}</button>`,'battle-result',true);render();saveGame();if(sound)sound.fx('arrival');}
function showRescue(){selected=null;chart.locate();openModal('还有下一次扬帆','RESCUED AT SEA',`<div class="event-art">${shipSVG()}</div><p class="event-copy">一艘过往商船救起了船员，拖着伤痕累累的圣加布里埃尔号返回${PORT_BY_ID[game.s.port].name}。</p><p class="event-note">救援耗时 4 天，支付了 15% 的金币并遗失一半货物。船体已临时修复，士气回到 50。你可以在酒馆工作筹款，修理船只后再次出发。</p><button class="primary" style="width:100%" data-action="rescue-continue">航海家的故事，还没有结束</button>`,'rescue',true);render();saveGame();}
function showEnding(){game.s.finished=true;openModal('属于你的大航海时代','A LEGEND OF THE SEVEN SEAS',`<div class="win-seal">${icon('compass')}</div><h3 class="win-title">七海的传奇</h3><p class="event-copy" style="text-align:center">从特茹河口的一面帆，<br>到横跨七海的名字。<br>你把未知的海岸，写进了世界的海图。</p><div class="summary-stats"><div><strong>${fmt(game.s.distance)}</strong><span>航行海里</span></div><div><strong>${game.s.visited.length}</strong><span>发现港口</span></div><div><strong>${game.s.day+1}</strong><span>航海天数</span></div></div><button class="primary" style="width:100%" data-action="ending-continue">海没有尽头 · 继续自由航行</button>`,'ending',true);saveGame();}
class SeaSound{
 constructor(){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=.16;this.master.connect(this.ctx.destination);this.active=true;const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*3,this.ctx.sampleRate),a=buffer.getChannelData(0);let prev=0;for(let i=0;i<a.length;i++){prev=(prev+Math.random()*.08-.04)/1.02;a[i]=prev*3;}this.noise=this.ctx.createBufferSource();this.noise.buffer=buffer;this.noise.loop=true;const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=500;const gain=this.ctx.createGain();gain.gain.value=.28;this.noise.connect(filter).connect(gain).connect(this.master);this.noise.start();this.step=0;this.timer=setInterval(()=>this.music(),3000);this.music();}
 note(freq,time,dur=.7,volume=.14,type='triangle'){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.001,time);g.gain.exponentialRampToValueAtTime(volume,time+.025);g.gain.exponentialRampToValueAtTime(.001,time+dur);o.connect(g).connect(this.master);o.start(time);o.stop(time+dur+.05);}
 music(){if(!this.active)return;const chords=[[146.83,220,293.66],[130.81,196,261.63],[164.81,220,329.63],[146.83,220,349.23]],ch=chords[this.step++%4],t=this.ctx.currentTime;ch.forEach((f,i)=>this.note(f,t+i*.24,2.2,.055));this.note(ch[this.step%3]*2,t+1.2,1.5,.06);}
 fx(name){if(!this.active)return;const t=this.ctx.currentTime;if(name==='cannon'||name==='hit'){const buf=this.ctx.createBuffer(1,this.ctx.sampleRate*.5,this.ctx.sampleRate),a=buf.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,3);const src=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();src.buffer=buf;f.type='lowpass';f.frequency.value=name==='cannon'?650:350;g.gain.value=.65;src.connect(f).connect(g).connect(this.master);src.start();return;}const notes=name==='arrival'?[293.66,369.99,440,587.33]:name==='danger'?[146.83,138.59,146.83]:name==='depart'?[196,261.63,329.63]:name==='error'?[164,130]:name==='trade'?[440,554]:[392];notes.forEach((f,i)=>this.note(f,t+i*.12,.5,.18));}
 toggle(){this.active=!this.active;if(this.active)this.ctx.resume();else this.ctx.suspend();return this.active;}
}
const ACTIONS={trade:showTrade,shipyard:showFleet,fleet:showFleet,tavern:showTavern,quests:showQuests,
 repair:()=>{if(safe(()=>game.repair())!==null){toast('船体修复完成。');refreshCurrent();}},refill:()=>{if(safe(()=>game.refill())!==null){toast('食物与淡水已补满。');refreshCurrent();}},
 feast:()=>{if(safe(()=>{game.feast();return true;})){toast('敬每一位远行的人！士气提升。');refreshCurrent();}},recruit:()=>{if(safe(()=>{game.recruit();return true;})){toast('新的水手已登船。');refreshCurrent();}},work:()=>{if(safe(()=>{game.work();return true;})){toast('两天工作结束，收到 420 G 与 24 单位补给。');refreshCurrent();}},hunt:()=>startBattle(true),
 motion:()=>{game.s.settings.motion=!game.s.settings.motion;saveGame();render();refreshCurrent();},export:exportSave,import:()=>$('importFile').click(),
 reset:()=>openModal('重新开始这段故事？','A NEW HORIZON',`<p class="confirm-copy">当前航程将被新的航程替代。若想以后继续，请先导出存档。</p><div class="event-actions"><button class="secondary" data-action="export">先导出当前存档</button><button class="primary" data-action="confirm-reset">确认 · 从里斯本重新起航</button></div>`,'reset'),
 'confirm-reset':()=>{closeModal(true);game=new SailingGame();selected=null;chart.game=game;chart.focus(-10,31,1.3);saveGame();render();toast('新的一页，从里斯本开始。');},
 'confirm-import':()=>{if(!importCandidate)return;closeModal(true);game=new SailingGame(importCandidate);importCandidate=null;selected=game.s.voyage?.to||null;chart.game=game;chart.locate();saveGame();render();toast('存档已恢复。愿季风与你同在。');},
 'battle-continue':()=>finishEvent(null),'rescue-continue':()=>closeModal(true),'ending-continue':()=>closeModal(true)
};
function bindUI(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){const view=b.dataset.view;if(view==='map'){closeModal();return;}({trade:showTrade,fleet:showFleet,quests:showQuests,journal:showJournal})[view]?.();return;}if(b.dataset.action){ACTIONS[b.dataset.action]?.();return;}if(b.dataset.port){const id=b.dataset.port;if(game.s.voyage){toast('抵港后才能重新规划航线。',true);return;}closeModal();if(id===game.s.port)showPort();else{selectPort(id);const p=PORT_BY_ID[id];chart.focus(p.lon,p.lat,Math.min(chart.zoom,1.3));}return;}if(b.dataset.buy||b.dataset.sell){const id=b.dataset.buy||b.dataset.sell,kind=b.dataset.buy?'buy':'sell',qty=Number($('qty-'+id).value),result=safe(()=>game.trade(id,qty,kind));if(result){toast(kind==='buy'?`购入成功，支付 ${fmt(result.amount)} G。`:`售出成功，收入 ${fmt(result.amount)} G，${result.profit>=0?'获利':'亏损'} ${fmt(Math.abs(result.profit))} G。`);refreshCurrent();if(sound)sound.fx('trade');}return;}if(b.dataset.upgrade){const result=safe(()=>game.upgrade(b.dataset.upgrade));if(result!==null){toast('改装完成，你的船更强大了。');refreshCurrent();}return;}if(b.dataset.claim){const q=safe(()=>game.claim(b.dataset.claim));if(q){toast(`完成「${q.title}」！获得 ${fmt(q.reward)} G 与 ${q.fame} 声望。`);if(sound)sound.fx('arrival');refreshCurrent();if(q.id==='legend'&&!game.s.finished)showEnding();}return;}if(b.dataset.event)resolveEvent(b.dataset.event);if(b.dataset.combat)combat(b.dataset.combat);});
 $('helpButton').addEventListener('click',showHelp);$('settingsButton').addEventListener('click',showSettings);$('saveButton').addEventListener('click',()=>saveGame(true));$('supplyButton').addEventListener('click',ACTIONS.refill);$('portListButton').addEventListener('click',()=>showPorts());$('closeModal').addEventListener('click',()=>closeModal());$('modalOverlay').addEventListener('click',e=>{if(e.target===$('modalOverlay'))closeModal();});$('sailButton').addEventListener('click',beginVoyage);$('dismissTutorial').addEventListener('click',()=>{game.s.tutorial=false;saveGame();render();});$('zoomIn').addEventListener('click',()=>chart.setZoom(chart.zoom*1.25));$('zoomOut').addEventListener('click',()=>chart.setZoom(chart.zoom*.8));$('centerMap').addEventListener('click',()=>chart.locate());$('worldView').addEventListener('click',()=>chart.full());$('pauseVoyage').addEventListener('click',togglePause);$('speedVoyage').addEventListener('click',()=>{game.s.settings.speed=game.s.settings.speed===4?1:game.s.settings.speed*2;saveGame();updateVoyage();});
 $('soundButton').addEventListener('click',()=>{try{if(!sound)sound=new SeaSound();else sound.toggle();$('soundButton').dataset.icon=sound.active?'sound':'soundoff';$('soundButton').setAttribute('aria-label',sound.active?'关闭声音':'开启声音');$('soundButton').title=sound.active?'关闭海风与音乐':'开启海风与音乐';icons($('soundButton').parentElement);toast(sound.active?'海风与航海旋律已开启。':'声音已关闭。');}catch{toast('此浏览器暂不支持音频合成。',true);}});
 document.addEventListener('input',e=>{if(e.target.id==='portSearch')$('portGrid').innerHTML=portListHTML(e.target.value);});document.addEventListener('change',e=>{if(e.target.id==='speedSetting'){game.s.settings.speed=Number(e.target.value);saveGame();updateVoyage();}});
 document.addEventListener('keydown',e=>{if(!gameplayActive)return;if(e.key==='Escape'){closeModal();return;}if(e.code==='Space'&&!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName)){e.preventDefault();togglePause();}if(e.key==='Tab'&&currentModal){const els=[...$('modal').querySelectorAll('button:not([hidden]):not(:disabled),input:not([hidden]),select')].filter(el=>el.getClientRects().length),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
 $('importFile').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000){toast('存档文件过大，请选择游戏导出的 JSON 文件。',true);return;}try{importCandidate=validateSave(JSON.parse(await file.text()));openModal('恢复这一段航程？','RESTORE A VOYAGE',`<p class="confirm-copy">${dateText(importCandidate.day)} · ${PORT_BY_ID[importCandidate.port].name}<br>持有 ${fmt(importCandidate.gold)} 金币，已发现 ${importCandidate.visited.length} 座港口。<br>恢复后会替代当前进度。</p><div class="event-actions"><button class="secondary" data-action="export">先备份当前存档</button><button class="primary" data-action="confirm-import">确认恢复</button></div>`,'import');}catch(err){toast('导入失败：'+err.message,true);}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){if(game.s.voyage)game.s.voyage.paused=true;saveGame();updateVoyage();}});window.addEventListener('beforeunload',()=>saveGame());}
function init(initialState){game=new SailingGame(initialState===undefined?loadGame():initialState);chart=new SeaChart($('worldMap'),selectPort);chart.game=game;selected=game.s.voyage?.to||null;$('shipArt').innerHTML=shipSVG();icons();bindUI();render();if(game.s.port!=='lisbon'||game.s.voyage)chart.locate();if(game.s.voyage)setTimeout(()=>toast('已恢复海上航程。点击「继续」即可再次启航。'),800);tickRAF=requestAnimationFrame(tickLoop);window.SailingDebug={game:()=>game,chart:()=>chart};}
