/* SOURCE: expanded-ui */
/* 图鉴、成就、城市编年史、研究，以及可关闭的演出层。 */
let atlasFilter='all',atlasSearch='',achievementFilter='all',storyFilter='active',storyPort=null,noticeTimer=null,fx;
function regionArt(p){if(['北海','波罗的海','北大西洋'].includes(p.region))return 5;if(['西非','东非','南非'].includes(p.region))return 1;if(['印度洋'].includes(p.region))return 2;if(['东亚','东南亚'].includes(p.region))return 3;if(['加勒比海','南美洲','太平洋群岛'].includes(p.region))return 4;if(['红海','阿拉伯海'].includes(p.region)||['istanbul','beirut','rhodes','tunis','algiers','alexandria','athens'].includes(p.id))return 0;return-1;}
function regionStyle(p){const a=regionArt(p);return a<0?'background-image:var(--home-art);background-size:cover;background-position:center':`background-image:var(--regional-art);background-size:300% 200%;background-position:${a%3*50}% ${Math.floor(a/3)*100}%`;}
function animalStyle(d){return`background-image:var(--marine-art);background-size:400% 300%;background-position:${d.art%4*100/3}% ${Math.floor(d.art/4)*50}%`;}
function entryArt(d,large=false){if(d.kind==='animal')return`<div class="atlas-art animal-art ${large?'large-art':''}" style="${animalStyle(d)}"></div>`;if(d.port)return`<div class="atlas-art region-art ${large?'large-art':''}" style="${regionStyle(PORT_BY_ID[d.port])}"><span>${d.kind==='heritage'?'HERITAGE':'PORT OF CALL'}</span></div>`;return`<div class="atlas-art chart-art ${large?'large-art':''}">${icon(d.kind==='continent'?'globe':'compass')}<span>${d.subtitle}</span></div>`;}
const kindLabels={port:'港口城市',continent:'大陆',sea:'海域',animal:'海洋生物',heritage:'历史遗产'};
function atlasCards(){const items=DISCOVERIES.filter(d=>(atlasFilter==='all'||atlasFilter==='found'&&game.s.atlas[d.id]||atlasFilter===d.kind)&&(!atlasSearch||(d.name+d.desc+d.hint).toLowerCase().includes(atlasSearch.toLowerCase())));return items.map(d=>{const found=game.s.atlas[d.id];return`<button class="atlas-card ${found?'recorded':'unrecorded'}" data-entry="${d.id}">${entryArt(d)}<div class="atlas-card-copy"><small>${kindLabels[d.kind]} <b>${found?'◆ 已记录':'◇ 待发现'}</b></small><h3>${d.name}</h3><p>${found?d.subtitle:d.hint}</p><span class="rarity rarity-${d.rarity}">${d.rarity}</span></div></button>`;}).join('')||'<p class="empty-state">没有匹配的条目。试试更改分类或搜索词。</p>';}
function atlasHTML(){const n=Object.keys(game.s.atlas).length;return`<div class="collection-intro"><div><span class="eyebrow">THE CABINET OF CURIOSITIES</span><h3>把世界，一页页装进航海日志。</h3><p>港口、海域、文明与海洋生命。每一次观察，都让未知变得具体。</p></div><div class="collection-count"><strong>${n}<em> / ${DISCOVERIES.length}</em></strong><span>世界图鉴收集度</span><div class="meter gold-meter"><span style="width:${n/DISCOVERIES.length*100}%"></span></div></div></div><div class="collection-toolbar"><div class="filter-tabs">${[['all','全部'],['found','已发现'],...Object.entries(kindLabels)].map(([id,name])=>`<button class="${atlasFilter===id?'active':''}" data-atlas-filter="${id}">${name}</button>`).join('')}</div><input type="search" id="atlasSearch" class="port-search" value="${escapeHTML(atlasSearch)}" placeholder="搜索名称、海域或线索" aria-label="搜索图鉴"></div><div class="atlas-grid" id="atlasGrid">${atlasCards()}</div>`;}
function showAtlas(){openModal('万物与七海 · 发现图鉴','THE EXPLORER’S ATLAS',atlasHTML(),'atlas');markExtraNav('atlas');}
function showEntry(id){const d=DISCOVERY_BY_ID[id];if(!d)return;const found=game.s.atlas[id];openModal(d.name,d.subtitle,`<div class="entry-detail ${found?'':'entry-locked'}">${entryArt(d,true)}<div class="entry-detail-copy"><span class="rarity rarity-${d.rarity}">${d.rarity} · ${kindLabels[d.kind]}</span><h3>${found?'你已经见过这片世界。':'海图上，还留着一处空白。'}</h3><p>${found?d.desc:'找到下面的线索，即可把这项记录收入你的图鉴。'}</p><div class="entry-clue"><small>${found?'发现记录':'发现线索'}</small><strong>${found?`${dateText(found.day)} · ${PORT_BY_ID[found.place]?.name||'公海'}`:d.hint}</strong></div><p class="entry-reward">首次记录奖励 · ${d.knowledge} 学识</p><div class="event-actions"><button class="secondary" data-action="atlas">返回图鉴</button>${d.port?`<button class="primary" data-story-nav="${d.port}">${d.port===game.s.port?'查看城市篇章':'在海图上规划航线'}</button>`:`<button class="primary" data-action="survey">准备一次考察</button>`}</div></div></div>`,'entry');}
function achievementHTML(){const claimed=game.s.achievements.length,ready=ACHIEVEMENTS.filter(a=>!game.s.achievements.includes(a.id)&&game.achievementValue(a)>=a.target).length;return`<div class="collection-intro"><div><span class="eyebrow">HONORS EARNED AT SEA</span><h3>海洋记得，你走过的每一步。</h3><p>每项成就只会结算一次，奖励可以用于下一次远航与研究。</p></div><div class="collection-count"><strong>${claimed}<em> / ${ACHIEVEMENTS.length}</em></strong><span>${ready?ready+' 项奖励等待领取':'已获得的航海荣誉'}</span></div></div><div class="filter-tabs achievement-tabs">${['all','ready','航海','贸易','战斗','探索','历史','成长'].map(id=>`<button data-achievement-filter="${id}" class="${achievementFilter===id?'active':''}">${id==='all'?'全部荣誉':id==='ready'?'可领取':id}</button>`).join('')}</div><div class="achievement-grid">${ACHIEVEMENTS.filter(a=>achievementFilter==='all'||achievementFilter==='ready'&&!game.s.achievements.includes(a.id)&&game.achievementValue(a)>=a.target||a.category===achievementFilter).map(a=>{const done=game.s.achievements.includes(a.id),value=Math.max(0,game.achievementValue(a)),ready=value>=a.target;return`<div class="achievement-card ${done?'claimed':ready?'ready':''}"><div class="medal">${icon(a.icon)}</div><div class="achievement-copy"><small>${a.category} ${done?'· 已授勋':''}</small><h3>${a.name}</h3><p>${a.desc}</p><div class="meter gold-meter"><span style="width:${Math.min(100,value/a.target*100)}%"></span></div><div class="achievement-bottom"><span>${done?'荣誉已记录':fmt(Math.min(value,a.target))+' / '+fmt(a.target)}</span><span>${fmt(a.gold)} G · ${a.knowledge} 学识</span></div><button class="small-button" data-achievement="${a.id}" ${done||!ready?'disabled':''}>${done?'◆ 已领取':ready?'领取成就奖励':'继续你的旅程'}</button></div></div>`;}).join('')||'<div class="empty-state">尚无可领取的成就。继续探索，下一份荣誉正在远方等你。</div>'}</div>`;}
function showAchievements(){openModal('荣誉殿堂','THE HALL OF HONORS',achievementHTML(),'achievements');markExtraNav('achievements');}
function storyHubHTML(){const total=Object.values(game.s.cityStories).reduce((n,c)=>n+c.stage,0),rows=PORTS.filter(p=>storyFilter==='all'||storyFilter==='local'&&p.id===game.s.port||storyFilter==='active'&&game.s.cityStories[p.id]?.stage<2||storyFilter==='done'&&game.s.cityStories[p.id]?.stage===2);return`<div class="collection-intro"><div><span class="eyebrow">CHRONICLES OF THE SEVEN SEAS</span><h3>每座港城，都有自己的主角。</h3><p>结识当地人物，完成独立篇章。历史回声提供背景，船长的故事由你续写。</p></div><div class="collection-count"><strong>${total}<em> / ${PORTS.length*2}</em></strong><span>已完成城市章节</span></div></div><div class="filter-tabs achievement-tabs">${[['local','当前城市'],['active','进行中的故事'],['all','全部港城'],['done','已完成']].map(([id,name])=>`<button data-story-filter="${id}" class="${storyFilter===id?'active':''}">${name}</button>`).join('')}</div><div class="story-grid">${rows.map(p=>{const st=CITY_STORIES[p.id],r=game.s.cityStories[p.id];return`<button class="story-card" data-story="${p.id}"><div class="story-card-art" style="${regionStyle(p)}"><span>${p.nation}</span><h3>${p.name}</h3><small>${p.en}</small></div><div class="story-card-copy"><small>${r?.stage===2?'◆ 故事已完成':r?'◈ 第 '+(r.stage+1)+' 章进行中':game.s.visited.includes(p.id)?'可以在当地开启':'前往港口结识当地人物'}</small><h4>${st.title}</h4><p>${st.npc}</p><div class="story-chapter-dots"><b class="${r?.stage>=1?'filled':''}"></b><b class="${r?.stage>=2?'filled':''}"></b></div></div></button>`;}).join('')||`<div class="empty-state">你的故事册还留着空白。<br>点击「当前城市」，聆听当地人的委托。<br><button class="small-button" data-story="${game.s.port}">走进${PORT_BY_ID[game.s.port].name}的故事</button></div>`}</div>`;}
function showStoryHub(){openModal('七海编年史 · 城市主线','STORIES TOLD ASHORE',storyHubHTML(),'storyHub');markExtraNav('stories');}
function storyHTML(port){const st=CITY_STORIES[port],p=PORT_BY_ID[port],r=game.s.cityStories[port],stage=r?.stage||0,done=stage===2,ch=st.chapters[Math.min(stage,1)],ready=r&&!done&&ch.goals.every(g=>game.objective(g,port).ready);return`<div class="story-hero" style="${regionStyle(p)}"><div><span>${p.nation} · ${p.region}</span><h3>${st.title}</h3><p>${st.npc}</p></div></div><div class="history-note"><small>历史回声</small><p>${st.history}</p><span>跨时代历史主题沙盒 · 下方人物与委托为原创虚构故事。</span></div>${done?`<div class="story-ending"><div class="medal">${icon('scroll')}</div><h3>故事已完成 · 跨海的友谊</h3><p>${st.ending}</p><span class="chip">最终选择：${r.choice==='merchant'?'开拓商路 · 获得额外商会资助':'分享知识 · 获得额外学识'}</span></div>`:`<div class="chapter-heading"><span>CHAPTER ${String(stage+1).padStart(2,'0')} / 02</span><h3>${ch.title}</h3></div><div class="objective-list">${ch.goals.map(g=>{const o=game.objective(g,port);return`<div class="objective ${o.ready?'complete':''}"><i>${o.ready?'◆':'◇'}</i><span>${o.label}</span><b>${Math.min(o.value,o.target)} / ${o.target}</b>${g.type==='visit'||g.type==='sell'?`<button class="text-button" data-story-nav="${g.type==='visit'?g.id:g.at}">航线 ↗</button>`:''}</div>`;}).join('')}</div><div class="chapter-rewards"><span>${fmt(ch.gold)} G</span><span>+ ${ch.fame} 声望</span><span>+ ${ch.knowledge} 学识</span></div>${!r?`<div class="event-actions"><button class="primary" data-story-start="${port}" ${game.s.port!==port||game.s.voyage?'disabled':''}>聆听委托 · 开启这座城的故事</button>${game.s.port!==port?`<button class="secondary" data-story-nav="${port}">规划前往${p.name}的航线</button>`:''}</div>`:stage===1?`<p class="modal-subtitle">完成故事后，选择你希望延续的联系：</p><div class="story-choices"><button class="choice-button" data-story-finish="${port}" data-choice="scholar" ${!ready||game.s.voyage?'disabled':''}>${icon('book')}<strong>分享知识</strong><span>额外获得 35 学识</span></button><button class="choice-button" data-story-finish="${port}" data-choice="merchant" ${!ready||game.s.voyage?'disabled':''}>${icon('trade')}<strong>开拓商路</strong><span>额外获得 900 G</span></button></div>`:`<button class="primary" style="width:100%" data-story-finish="${port}" data-choice="scholar" ${!ready||game.s.voyage?'disabled':''}>${ready?'递交报告 · 完成本章':'完成目标后递交报告'}</button>`}<p class="market-foot">交付类目标会消耗货舱中的指定货物，必须在这座城市完成。贸易与访问记录可累计；无交付需求的章节可在任意港口通过信使递交报告。</p>`}<button class="text-button" style="margin-top:20px" data-action="stories">← 返回七海编年史</button>`;}
function showStory(port=game.s.port){storyPort=port;openModal(PORT_BY_ID[port].name+' · 城市篇章','A CITY, A STORY',storyHTML(port),'story');markExtraNav('stories');}
function surveyHTML(){const port=game.s.voyage?.to||game.s.port,p=PORT_BY_ID[port],n=game.s.surveys[port]||0,list=MARINE_SPECIES.filter(a=>a.regions.includes(p.region));return`<div class="survey-intro">${icon('compass')}<div><h3>在${p.name}附近，留意世界的细节。</h3><p>当地考察消耗 1 天与 4 单位补给。记录城市遗产，并寻找这一地区的海洋生命。</p></div></div><div class="survey-stats"><span>本地考察 <b>${n} 次</b></span><span>考察效率 <b>× ${1+game.s.research.naturalism}</b></span><span>可用补给 <b>${game.s.supplies}</b></span></div><div class="field-note"><small>领航员的线索</small><p>${list.length?'这片海域可能观察到：'+list.map(a=>a.name).join('、')+'。重复考察或研究博物学，可更快遇见珍稀物种。':'这片海域的城市遗产和水文记录同样值得书写。前往热带海域或北方海岸，可发现不同海洋生命。'}</p></div><button class="primary" style="width:100%;margin-top:20px" data-action="do-survey" ${game.s.supplies<4?'disabled':''}>${icon('compass')} 整理行囊 · 开始考察</button><p class="market-foot">近岸考察在停泊港组织，自动记录当地遗产。没有新发现的考察仍会积累 3 学识；海域会在远航途中自动记录。</p>`;}
function showSurvey(){if(game.s.voyage){toast('抵港后可组织近岸考察；远航中会自动记录海域与海上遭遇。');return;}openModal('自然与文明的观察课','FIELD EXPEDITION',surveyHTML(),'survey');}
function performSurvey(){const ids=safe(()=>game.survey());if(ids===null)return;if(fx)fx.burst(innerWidth*.5,innerHeight*.45,'discovery');if(sound)sound.fx('discovery');replaceBody(`<div class="expedition-result"><span class="eyebrow">FIELD NOTES ADDED</span><h3>${ids.length?'新的发现，写进了你的日志。':'耐心观察，也是航海的一部分。'}</h3><p>消耗 1 天与 4 补给，船员士气 +2。${ids.length?'点击新记录，查看详情。':'获得 3 学识。继续研究或更换海域，寻找新的线索。'}</p></div><div class="atlas-grid result-grid">${ids.map(id=>{const d=DISCOVERY_BY_ID[id];return`<button class="atlas-card recorded" data-entry="${id}">${entryArt(d)}<div class="atlas-card-copy"><small>${kindLabels[d.kind]} · ${d.rarity}</small><h3>${d.name}</h3><p>+ ${d.knowledge} 学识</p></div></button>`;}).join('')}</div><div class="event-actions" style="margin-top:22px"><button class="primary" data-action="do-survey" ${game.s.supplies<4?'disabled':''}>再考察一天</button><button class="secondary" data-action="atlas">查看完整图鉴</button></div>`);}
function researchHTML(){return`<div class="collection-intro"><div><span class="eyebrow">KNOWLEDGE IS A FAIR WIND</span><h3>探索所得，成为下一次远航的力量。</h3><p>发现图鉴、完成城市篇章与成就，都可以积累学识。</p></div><div class="collection-count"><strong>${fmt(game.s.knowledge)}</strong><span>可用学识</span></div></div><div class="research-grid">${RESEARCH.map(r=>{const lv=game.s.research[r.id];return`<div class="research-card"><div class="research-icon">${icon(r.icon)}</div><span class="eyebrow">DISCIPLINE ${r.id.toUpperCase()}</span><h3>${r.name}</h3><p>${r.desc}</p><div class="level-dots">${Array.from({length:4},(_,i)=>`<b class="${i<lv?'filled':''}"></b>`).join('')}</div><button class="primary" data-research="${r.id}" ${lv>=4||game.s.voyage?'disabled':''}>${lv>=4?'研究已臻完善':'研究 '+(lv+1)+' 级 · '+r.cost*(lv+1)+' 学识'}</button></div>`;}).join('')}</div><p class="market-foot">研究可在任何港口进行。商业契约的买卖优惠始终保留价差，同港即时倒卖不会凭空获利。</p>`;}
function showResearch(){openModal('航海学堂','THE NAVIGATOR’S ACADEMY',researchHTML(),'research');markExtraNav('research');}
function markExtraNav(action){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.action===action));}
function installExpansionUI(){const rail=document.querySelector('.navrail'),spacer=rail.querySelector('.nav-spacer');for(const[action,label,ico]of[['stories','篇章','scroll'],['atlas','图鉴','globe'],['achievements','成就','star'],['research','学堂','compass']]){const b=document.createElement('button');b.className='nav-item';b.dataset.action=action;b.innerHTML=`<i>${icon(ico)}</i><span>${label}</span>${action==='achievements'?'<b class="nav-badge" id="achievementBadge" hidden></b>':''}`;rail.insertBefore(b,spacer);}rail.classList.add('expanded-rail');const header=document.querySelector('.map-header');const actions=document.createElement('div');actions.className='map-extra-actions';actions.innerHTML='<button class="text-button" data-action="local-story">城市篇章 ↗</button><button class="text-button" data-action="survey">'+icon('compass')+' 考察</button>';header.insertBefore(actions,$('portListButton'));const facility=document.querySelector('.facility-title');facility.insertAdjacentHTML('afterend',`<button class="facility city-facility" data-action="local-story"><i>${icon('scroll')}</i><div><strong>城市篇章 <b id="localStoryDot">◆</b></strong><span id="localStoryHint">聆听这座城的故事</span></div><b>›</b></button>`);document.querySelector('.statusbar>span:last-child').innerHTML='七海编年史 <b>·</b> 2.0';document.querySelector('.brand h1 span').textContent='七海编年史';const panel=document.createElement('button');panel.id='discoveryNotice';panel.className='discovery-notice';panel.hidden=true;document.body.append(panel);panel.addEventListener('click',()=>{const n=panel._notice;panel.hidden=true;if(n?.type==='achievement')showAchievements();else if(n?.type==='chapter')showStory(n.id);else if(n)showEntry(n.id);});fx=new WorldFX();icons();}
function updateExpansionUI(){const p=PORT_BY_ID[game.s.port],a=regionArt(p),harbor=document.querySelector('.harbor-art');if(a<0){harbor.style.cssText=regionStyle(p);harbor.querySelector('img').style.opacity='1';}else{harbor.style.cssText+=';'+regionStyle(p);harbor.querySelector('img').style.opacity='0';}const record=game.s.cityStories[p.id];$('localStoryHint').textContent=record?.stage===2?'这座城已经记住你的名字':CITY_STORIES[p.id].title;$('localStoryDot').textContent=record?.stage===2?'✓':'◆';const ready=ACHIEVEMENTS.filter(a=>!game.s.achievements.includes(a.id)&&game.achievementValue(a)>=a.target).length;$('achievementBadge').hidden=!ready;$('achievementBadge').textContent=ready;$('captainRank').textContent=rank()+' · '+game.s.knowledge+' 学识';$('tutorial').querySelector('p').textContent='点击港口规划航线，走进城市篇章，收集万物图鉴。';}
function pumpNotice(){if(currentModal||!game.notices?.length||!$('discoveryNotice').hidden)return;const n=game.notices.shift(),panel=$('discoveryNotice');panel._notice=n;panel.innerHTML=`<div class="notice-medal">${icon(n.type==='achievement'?'star':n.type==='chapter'?'scroll':'compass')}</div><div><small>${n.type==='achievement'?'ACHIEVEMENT UNLOCKED':n.type==='chapter'?'A CHAPTER COMPLETED':'A NEW DISCOVERY'}</small><strong>${n.title}</strong><p>${n.text}</p></div><span>↗</span>`;panel.hidden=false;if(sound)sound.fx(n.type==='achievement'?'achievement':'discovery');if(fx)fx.burst(innerWidth*.72,100,'discovery',24);clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>panel.hidden=true,3800);saveGame();}
class WorldFX{
 constructor(){this.canvas=document.createElement('canvas');this.canvas.className='world-fx';document.body.append(this.canvas);this.c=this.canvas.getContext('2d');this.particles=[];this.rainUntil=0;this.flash=0;this.last=0;this.resize=()=>{this.canvas.width=innerWidth;this.canvas.height=innerHeight;};this.resize();addEventListener('resize',this.resize);this.raf=requestAnimationFrame(t=>this.frame(t));}
 burst(x,y,type='discovery',count=65){if(!game.s.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const cannon=type==='cannon';for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,speed=(cannon?7:4)*Math.random()+.4;this.particles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed-(cannon?0:2),life:1,decay:.012+Math.random()*.012,size:Math.random()*(cannon?6:3)+1,color:cannon?(i%2?'#e3aa55':'#d7cbc0'):['#e9cb88','#95c4b5','#f5e9be'][i%3]});}if(cannon)this.flash=.17;}
 storm(){this.rainUntil=performance.now()+4200;this.flash=.25;}
 frame(t){this.raf=null;if(typeof gameplayActive!=='undefined'&&(!gameplayActive||document.hidden))return;const c=this.c;if(t-this.last>25){const dt=Math.min(2,(t-this.last)/33||1);this.last=t;c.clearRect(0,0,this.canvas.width,this.canvas.height);if(this.flash>0){c.fillStyle=`rgba(255,239,201,${this.flash})`;c.fillRect(0,0,this.canvas.width,this.canvas.height);this.flash*=.78;if(this.flash<.005)this.flash=0;}for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.04*dt;p.life-=p.decay*dt;c.globalAlpha=Math.max(0,p.life);c.fillStyle=p.color;c.save();c.translate(p.x,p.y);c.rotate(p.life*4);c.fillRect(-p.size/2,-p.size/2,p.size,p.size*.55);c.restore();}this.particles=this.particles.filter(p=>p.life>0);c.globalAlpha=1;if(t<this.rainUntil&&game.s.settings.motion){c.strokeStyle='#c0d9d947';c.lineWidth=.8;for(let i=0;i<100;i++){const x=(i*157.3+t*.09)%this.canvas.width,y=(i*77+t*.65)%this.canvas.height;c.beginPath();c.moveTo(x,y);c.lineTo(x-10,y+22);c.stroke();}}}this.raf=requestAnimationFrame(t=>this.frame(t));}
}
const originalOpenModal=openModal;openModal=function(title,eyebrow,body,type,locked=false){$('modal').classList.toggle('wide-modal',['atlas','storyHub','achievements','research'].includes(type));originalOpenModal(title,eyebrow,body,type,locked);};
const originalRender=render;render=function(){game.syncWorld();originalRender();if($('localStoryHint'))updateExpansionUI();};
const originalRefreshCurrent=refreshCurrent;refreshCurrent=function(){originalRefreshCurrent();if(currentModal==='story')replaceBody(storyHTML(storyPort));if(currentModal==='storyHub')replaceBody(storyHubHTML());if(currentModal==='achievements')replaceBody(achievementHTML());if(currentModal==='research')replaceBody(researchHTML());};
const originalCombat=combat;combat=function(action){if(battle&&!battle.busy&&action!=='flee'){const el=$('enemyBattleShip'),r=el?.getBoundingClientRect();if(r)fx.burst(r.x+r.width*.5,r.y+r.height*.6,'cannon',75);}originalCombat(action);};
const originalShowEvent=showEvent;showEvent=function(type){originalShowEvent(type);if(type==='storm')fx.storm();};
const originalResolveEvent=resolveEvent;resolveEvent=function(action){if(action==='dolphins')game.discover('animal:dolphin','公海');originalResolveEvent(action);};
const originalFinishBattle=finishBattle;finishBattle=function(result){if(result==='won')fx.burst(innerWidth*.5,innerHeight*.4,'discovery',120);originalFinishBattle(result);};
const originalSeaFx=SeaSound.prototype.fx;SeaSound.prototype.fx=function(name){if(!this.active)return;if(name==='discovery'||name==='achievement'){const t=this.ctx.currentTime,notes=name==='achievement'?[261.63,329.63,392,523.25,659.25]:[392,493.88,587.33,783.99];notes.forEach((f,i)=>this.note(f,t+i*.095,1.1,.18,'sine'));return;}originalSeaFx.call(this,name);};
Object.assign(ACTIONS,{atlas:showAtlas,achievements:showAchievements,stories:showStoryHub,'local-story':()=>showStory(),research:showResearch,survey:showSurvey,'do-survey':performSurvey});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.atlasFilter){atlasFilter=b.dataset.atlasFilter;replaceBody(atlasHTML());}if(b.dataset.entry)showEntry(b.dataset.entry);if(b.dataset.achievementFilter){achievementFilter=b.dataset.achievementFilter;replaceBody(achievementHTML());}if(b.dataset.achievement){const r=safe(()=>game.claimAchievement(b.dataset.achievement));if(r){fx.burst(innerWidth*.5,innerHeight*.45);if(sound)sound.fx('achievement');toast(`获得「${r.name}」：${fmt(r.gold)} G 与 ${r.knowledge} 学识。`);refreshCurrent();}}if(b.dataset.storyFilter){storyFilter=b.dataset.storyFilter;replaceBody(storyHubHTML());}if(b.dataset.story)showStory(b.dataset.story);if(b.dataset.storyStart){if(safe(()=>{game.startStory(b.dataset.storyStart);return true;}))replaceBody(storyHTML(b.dataset.storyStart));}if(b.dataset.storyFinish){const r=safe(()=>game.finishStory(b.dataset.storyFinish,b.dataset.choice));if(r){fx.burst(innerWidth*.5,innerHeight*.4);if(sound)sound.fx('achievement');replaceBody(storyHTML(b.dataset.storyFinish));toast(`篇章完成！获得 ${fmt(r.gold)} G 与 ${r.knowledge} 学识。`);}}if(b.dataset.storyNav){const id=b.dataset.storyNav;if(game.s.voyage){toast('当前正在远航，抵港后可重新规划。',true);return;}if(id===game.s.port){showStory(id);return;}closeModal();selectPort(id);const p=PORT_BY_ID[id];chart.focus(p.lon,p.lat,Math.min(chart.zoom,1.1));}if(b.dataset.research){if(safe(()=>game.study(b.dataset.research))!==null){toast('新的知识已经用于船只与船员。');refreshCurrent();if(sound)sound.fx('discovery');}}});
document.addEventListener('input',e=>{if(e.target.id==='atlasSearch'){atlasSearch=e.target.value;$('atlasGrid').innerHTML=atlasCards();}});
