/* SOURCE: portraits-ui */
/* 第三版全画册界面：独立配图、人物册与可回看的任务对话。 */
let peopleTab='crew',peopleSearch='',dialogue=null,dialogueTimer=null;
function pictureStyle(id,thumbnail=false){const a=ILLUSTRATIONS[id];if(!a)throw Error('缺少插画索引：'+id);const[x,y,w,h]=a.focusCrop||[0,0,1,1];return`background-image:var(--art-${thumbnail?'thumb-':''}${a.sheet});background-size:${a.focusCrop?100/w:a.cols*100}% ${a.focusCrop?100/h:a.rows*100}%;background-position:${a.focusCrop?(w===1?0:x/(1-w)*100):a.cols===1?0:a.cell%a.cols*100/(a.cols-1)}% ${a.focusCrop?(h===1?0:y/(1-h)*100):a.rows===1?0:Math.floor(a.cell/a.cols)*100/(a.rows-1)}%;--tile-ratio:${a.ratio}`;}
function painting(id,label,classes=''){const thumbnail=/\b(round-portrait|port-index-art|person-art|captain-mini-art|credit-thumb|dialogue-portrait|event-avatar)\b/.test(classes)||(classes.includes('atlas-art')&&!classes.includes('large-art'));const geometry=pictureStyle(id,thumbnail).replace(/^background-image:[^;]+;/,'');return `<div class="painting ${classes}" role="img" aria-label="${escapeHTML(label)}" data-art-state="queued" style="--tile-ratio:${ILLUSTRATIONS[id].ratio}"><div class="painting-native" data-art-id="${id}" data-art-tier="${thumbnail?'preview':'full'}" style="${geometry}"></div><span class="art-placeholder" aria-hidden="true"><strong>${escapeHTML(label)}</strong><span class="art-status">画作等待载入</span></span></div>`;}
regionStyle=function(p){return pictureStyle('port:'+p.id,true)+';background-size:cover;background-position:center';};
entryArt=function(d,large=false){return painting(d.id,d.name+' · 图鉴配图',`atlas-art illustrated-art ${d.kind==='animal'?'animal-art':''} ${large?'large-art':''}`);};
function artCredit(id){const c=typeof ART_CREDITS==='undefined'?null:ART_CREDITS[id];if(!c)return '<p class="art-credit">游戏原创绘画素材 · AI 辅助生成</p>';const url=/^https:\/\//.test(c.sourceUrl||'')?c.sourceUrl:'',lic=/^https?:\/\//.test(c.licenseUrl||'')?c.licenseUrl:'';return `<p class="art-credit"><strong>${escapeHTML(c.title||'画作')}</strong><span>${escapeHTML(c.artist||'作者见来源页')} · ${lic?`<a href="${escapeHTML(lic)}" target="_blank" rel="noopener noreferrer">${escapeHTML(c.license)}</a>`:escapeHTML(c.license||'授权见来源页')}</span>${c.visualNote?`<span>${escapeHTML(c.visualNote)}</span>`:''}${url?`<a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">查看原作与授权 ↗</a>`:''}</p>`;}
function artLabel(id){if(DISCOVERY_BY_ID[id])return DISCOVERY_BY_ID[id].name;const [kind,key]=id.split(':');if(kind==='npc')return PORT_BY_ID[key].name+' · '+CITY_STORIES[key].npc;if(kind==='crew')return OFFICER_BY_ID[key]?.name||({merchant:'纳迪姆',sailor:'马特奥',pirate:'维克托 · 黑鸦'})[key];return({storm:'风暴',wreck:'漂流船骸',merchant:'商船',dolphins:'海豚群',battle:'海上交战',tavern:'水手酒馆'})[key]||id;}
function creditsHTML(){const all=Object.entries(ILLUSTRATIONS);return `<div class="collection-intro"><div><span class="eyebrow">THE ART BEHIND THE ATLAS</span><h3>画中世界，亦有来处。</h3><p>历史绘画、遗产影像与原创海景共同组成这本航海册。历史画作和遗迹照片用于呈现风景与文化，并非游戏年代的现场记录。人物为原创虚构角色，历史肖像仅作角色视觉参考；同一原作可能用于多位人物。</p><p>离线版内嵌全部图片；在线版按需载入画作。来源链接仅在主动点击时打开。开放授权图片的原作、作者与具体许可如下；展示时使用了缩放、画面裁切与格式转换。</p></div></div><div class="art-credits-list">${all.map(([id])=>`<article class="art-credit-item">${painting(id,artLabel(id),'credit-thumb')}<div><h3>${escapeHTML(artLabel(id))}</h3>${artCredit(id)}</div></article>`).join('')}</div>`;}
function showCredits(){openModal('画作与致谢','ARTWORK & ATTRIBUTION',creditsHTML(),'credits');}
const illustratedShowEntry=showEntry;showEntry=function(id){illustratedShowEntry(id);if(DISCOVERY_BY_ID[id])$('modalBody').insertAdjacentHTML('beforeend',artCredit(id));};
const v2StoryHTML=storyHTML;
storyHTML=function(port){const p=PORT_BY_ID[port],st=CITY_STORIES[port],met=game.s.conversations[port]?.met;let html=v2StoryHTML(port);html=html.replace(/^<div class="story-hero"[\s\S]*?<\/div><\/div>/,`<div class="illustrated-story-hero">${painting('port:'+port,p.name)}<div class="story-hero-shade"></div><div class="illustrated-story-title"><span>${p.nation} · ${p.region}</span><h3>${st.title}</h3><p>${p.name} / ${p.en}</p></div>${painting('npc:'+port,st.npc,'story-hero-portrait')}</div><div class="npc-strip">${painting('npc:'+port,st.npc,'round-portrait')}<div><small>${met?'已经相识':'当地联系人'}</small><strong>${st.npc}</strong></div><button class="small-button" data-talk="${port}" ${game.s.voyage||game.s.port!==port?'disabled':''}>${met?'再聊一会儿':'与 TA 交谈'} ↗</button></div>`);
html=html.replaceAll('data-story-start=','data-talk-start=').replaceAll('data-story-finish=','data-talk-complete=');return html;};
const v2FleetHTML=fleetHTML;
fleetHTML=function(){const c=OFFICER_BY_ID[game.s.officer]||OFFICER_BY_ID.mate;return`<div class="crew-duty-banner">${painting('crew:'+c.id,c.name,'round-portrait')}<div><small>本航次值勤</small><strong>${c.name} · ${c.role}</strong><p>${c.perk}</p></div><button class="small-button" data-action="people">船长与船员</button></div>`+v2FleetHTML().replace(/维修每点耐久消耗 5 金币/g,`维修每点耐久消耗 ${game.s.officer==='carpenter'?4:5} 金币`).replace(/完全修理 · ([\d,]+) G/g,`完全修理 · ${fmt((game.maxHull-game.s.hull)*(game.s.officer==='carpenter'?4:5))} G`);};
const v2TavernHTML=tavernHTML;
tavernHTML=function(){const p=PORT_BY_ID[game.s.port],st=CITY_STORIES[p.id];return`<div class="tavern-panorama">${painting('event:tavern','灯火中的水手酒馆')}<div><small>THE SAILOR’S REST</small><h3>一张桌子，坐得下不同的远方。</h3></div></div><div class="tavern-people"><button data-person="crew:sailor">${painting('crew:sailor','老水手','round-portrait')}<span>听老水手说说</span></button><button data-talk="${p.id}">${painting('npc:'+p.id,st.npc,'round-portrait')}<span>${st.npc}</span></button><button data-action="people">${painting('crew:mate','大副伊莎贝尔','round-portrait')}<span>安排船员值勤</span></button></div>`+v2TavernHTML();};
portListHTML=function(filter=''){return PORTS.filter(p=>(p.name+p.en+p.region+p.nation).toLowerCase().includes(filter.toLowerCase())).map(p=>{const v=game.s.visited.includes(p.id),days=p.id===game.s.port?0:game.estimate(p.id).days;return`<button class="port-index-item illustrated-port-item" data-port="${p.id}">${painting('port:'+p.id,p.name,'port-index-art')}<div><strong>${p.name}</strong><small>${p.region} · ${p.nation}</small><em>${p.id===game.s.port?'当前停泊':`预计 ${days} 天 · ${p.special}`}</em></div>${v?'<span class="visited-tag">◆</span>':''}</button>`;}).join('')||'<p class="empty-state">没有匹配的港口。</p>';};
showPorts=function(){openModal('八十港 · 航路与风景','PORTS OF THE SEVEN SEAS',`<div class="port-region-tabs filter-tabs">${[['','全部港口'],['大明','中国沿海'],['日本','日本诸港'],['琉球','琉球'],['休达','休达']].map(([q,n])=>`<button data-port-query="${q}">${n}</button>`).join('')}</div><input id="portSearch" class="port-search" type="search" placeholder="搜索城市、国家或海域…" aria-label="搜索港口"><div class="port-grid" id="portGrid">${portListHTML()}</div>`,'ports');};
function peopleHTML(){const active=OFFICER_BY_ID[game.s.officer]||OFFICER_BY_ID.mate;return`<div class="collection-intro"><div><span class="eyebrow">FACES BEHIND THE VOYAGES</span><h3>每一次远航，都有人与你同行。</h3><p>船长、船员，以及八十座港城里等候回信的人。</p></div><div class="collection-count"><strong>${Object.values(game.s.conversations).filter(c=>c.met).length}<em> / ${PORTS.length}</em></strong><span>已交谈的城市人物</span></div></div><div class="collection-toolbar"><div class="filter-tabs">${[['crew','船长与船员'],['npc','港城人物']].map(([id,name])=>`<button data-people-tab="${id}" class="${peopleTab===id?'active':''}">${name}</button>`).join('')}</div>${peopleTab==='npc'?`<input class="port-search" id="peopleSearch" value="${escapeHTML(peopleSearch)}" placeholder="搜索人物、城市或国家" aria-label="搜索人物">`:''}</div>${peopleTab==='crew'?`<div class="duty-note"><strong>当前值勤：${active.role} ${active.name}</strong><p>${active.perk}。每次由一人负责值勤，只能在港口调整；全体船员继续随船同行。</p></div>`:''}<div class="people-grid" id="peopleGrid">${peopleCards()}</div>`;}
function peopleCards(){if(peopleTab==='crew')return CREW.map(c=>`<article class="person-card ${game.s.officer===c.id?'on-duty':''}"><button class="person-art-button" data-person="crew:${c.id}">${painting('crew:'+c.id,c.name,'person-art')}<span>${c.role}</span></button><div class="person-card-copy"><small>${c.origin}</small><h3>${c.name}</h3><p>${c.perk}</p>${c.id==='captain'?'<button class="small-button" data-person="crew:captain">翻开船长手记</button>':`<button class="small-button" data-appoint="${c.id}" ${game.s.voyage||game.s.officer===c.id?'disabled':''}>${game.s.officer===c.id?'◆ 正在值勤':'安排值勤'}</button>`}</div></article>`).join('');return PORTS.filter(p=>(p.name+p.nation+CITY_STORIES[p.id].npc).includes(peopleSearch)).map(p=>{const st=CITY_STORIES[p.id],met=game.s.conversations[p.id]?.met;return`<article class="person-card ${met?'met':''}"><button class="person-art-button" data-person="npc:${p.id}">${painting('npc:'+p.id,st.npc,'person-art')}<span>${met?'◆ 已交谈':game.s.visited.includes(p.id)?'可以结识':'尚未相识'}</span></button><div class="person-card-copy"><small>${p.name} · ${p.nation}</small><h3>${st.npc}</h3><p>${st.title}</p><button class="small-button" data-person="npc:${p.id}">查看人物</button></div></article>`;}).join('')||'<p class="empty-state">没有匹配的人物。</p>';}
function showPeople(){openModal('船长与众生 · 人物册','THE PEOPLE OF THE SEVEN SEAS',peopleHTML(),'people');}
function showPerson(id){const [kind,key]=id.split(':');if(kind==='npc'){const p=PORT_BY_ID[key],st=CITY_STORIES[key];if(!p||!st)return;openModal(st.npc,p.name+' · '+p.nation,`<div class="person-detail">${painting(id,st.npc,'person-detail-art')}<div><span class="eyebrow">A VOICE FROM ${p.en}</span><h3>${st.title}</h3><p>${DIALOGUES[key].request}</p><p class="person-bio">${p.desc}</p><div class="event-actions"><button class="primary" data-talk="${key}" ${game.s.port!==key||game.s.voyage?'disabled':''}>当面交谈</button><button class="secondary" data-story="${key}">城市篇章</button></div><button class="text-button" data-action="people">← 返回人物册</button></div></div>`,'person');return;}const extras={sailor:{name:'马特奥',role:'老水手',origin:'码头与远海',bio:PORT_BY_ID[game.s.port].rumor,line:'第一次出海时，每个人都会紧张。把补给装好，先走一段近路；海会慢慢教你。',perk:'酒馆可以招募水手、恢复士气与接受码头工作。'},merchant:{name:'纳迪姆',role:'远洋商人',origin:'黎凡特商路',bio:'在不同海域之间买卖货物，认得许多港口的行情。',line:'看清买卖的差价，也把航程、工资和补给算进去。',perk:'在交易所比较货价。'},pirate:{name:'维克托 · 黑鸦',role:'海盗船长',origin:'黑鸦号',bio:'漂泊在商路边缘的对手，帆下藏着凶险的火炮。',line:'追逐黄金的人，应该知道这片海并不总是温柔。',perk:'击败黑鸦号能赢得战利品。'}};const c=OFFICER_BY_ID[key]||extras[key];if(!c)return;openModal(c.name,c.role+' · '+c.origin,`<div class="person-detail">${painting(id,c.name,'person-detail-art')}<div><span class="eyebrow">A LIFE AT SEA</span><h3>${c.role}</h3><p>${c.bio}</p><blockquote>“${c.line}”</blockquote><div class="duty-note">${c.perk}</div><div class="event-actions">${OFFICER_BY_ID[key]&&key!=='captain'?`<button class="primary" data-appoint="${key}" ${game.s.voyage||game.s.officer===key?'disabled':''}>${game.s.officer===key?'正在值勤':'安排值勤'}</button>`:''}<button class="secondary" data-action="people">返回人物册</button></div></div></div>`,'person');}
function conversationLines(port,mode){const p=PORT_BY_ID[port],d=DIALOGUES[port],st=CITY_STORIES[port],r=game.s.cityStories[port];if(mode==='history')return[{who:'npc',text:d.history},{who:'captain',text:'我会把这段历史单独记下，让后来的人分得清故事与史实。'},{who:'npc',text:'也请听听今天生活在这里的人。远处的年代，仍会在一间作坊、一条水道里留下回声。'}];if(mode==='complete')return[{who:'captain',text:`关于「${st.chapters[r?.stage||0].title}」，约定的事情已经办妥。`},{who:'npc',text:r?.stage===1?d.ending:'我看见了你带回的记录。谢谢你认真对待这件事，我们终于可以继续下一步。'}];if(mode==='work')return[{who:'npc',text:!r?d.request:r.stage===2?d.ending:r.stage===1?d.second:d.request},{who:'captain',text:r?.stage===2?'愿这份联系一直留在往来的船帆里。':'我会留意目标清单，也会把沿途值得记录的事带回来。'}];return[{who:'npc',text:game.s.conversations[port]?.met?`船长，你又来了。${r?.stage===2?d.ending:'码头一直有人问起你的航程。'}`:d.welcome},{who:'captain',text:`我想听听${p.name}的故事，也想知道这里有什么值得我们一起完成的事。`},{who:'npc',text:r?.stage===1?d.second:r?.stage===2?d.farewell:d.request}];}
function dialogueHTML(){const t=dialogue,p=PORT_BY_ID[t.port],st=CITY_STORIES[t.port],line=t.lines[t.index],r=game.s.cityStories[t.port];return`<div class="dialogue-stage">${painting('port:'+p.id,p.name,'dialogue-backdrop')}<div class="dialogue-vignette"></div><div class="dialogue-location"><small>${p.nation}</small><strong>${p.name}</strong><span>${dateText(game.s.day)}</span></div>${painting('crew:captain','船长阿尔瓦罗',`dialogue-portrait captain-portrait ${line.who==='captain'?'speaking':''}`)}${painting('npc:'+p.id,st.npc,`dialogue-portrait npc-portrait ${line.who==='npc'?'speaking':''}`)}<div class="dialogue-box"><div class="dialogue-speaker"><strong>${line.who==='npc'?st.npc:'阿尔瓦罗 · 德·索萨'}</strong><span>${t.mode==='history'?'历史回声':'原创剧情'} · ${t.index+1} / ${t.lines.length}</span></div><p id="dialogueText" class="dialogue-text" aria-label="${escapeHTML(line.text)}"></p><button class="text-button dialogue-reveal" data-dialogue-reveal="true">显示整句</button><div class="dialogue-controls">${t.index<t.lines.length-1?'<button class="primary" data-dialogue-next="true">继续对话 <span>↵</span></button>':`<div class="dialogue-options">${t.mode==='complete'?`<button class="primary" data-dialogue-submit="true">${r?.stage===1?(t.choice==='merchant'?'开拓商路 · 领取回报':'分享知识 · 领取回报'):'递交报告 · 完成本章'}</button>`:!r?'<button class="primary" data-dialogue-accept="true">这份委托，交给我吧。</button>':r.stage<2?'<button class="primary" data-dialogue-goals="true">查看当前目标</button>':''}${t.mode!=='history'?'<button class="secondary" data-dialogue-topic="history">想再听听这里的历史。</button>':''}${t.mode==='history'?'<button class="secondary" data-dialogue-topic="work">回到我们的委托。</button>':''}<button class="secondary" data-dialogue-goals="true">下次再聊 · 返回篇章</button></div>`}</div></div></div>`;}
function stopDialogueTyping(){if(dialogueTimer)clearInterval(dialogueTimer);dialogueTimer=null;}
function typeDialogue(){stopDialogueTyping();if(!dialogue||currentModal!=='dialogue')return;const text=dialogue.lines[dialogue.index].text,el=$('dialogueText');if(!el)return;let cursor=0;dialogue.revealed=!game.s.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;el.textContent=dialogue.revealed?text:'';if(dialogue.revealed)return;dialogueTimer=setInterval(()=>{if(currentModal!=='dialogue'||!dialogue){stopDialogueTyping();return;}cursor=Math.min(text.length,cursor+2);el.textContent=text.slice(0,cursor);if(cursor%10===0&&sound)sound.fx('quill');if(cursor===text.length){dialogue.revealed=true;stopDialogueTyping();}},28);}
function revealDialogue(){if(!dialogue)return;stopDialogueTyping();const el=$('dialogueText');if(el)el.textContent=dialogue.lines[dialogue.index].text;dialogue.revealed=true;}
function showConversation(port,mode='greeting',choice='scholar'){if(game.s.voyage||game.s.port!==port){toast('请抵达当地，再与这位人物当面交谈。',true);return;}const lines=conversationLines(port,mode);if(safe(()=>game.recordConversation(port,mode))===null)return;dialogue={port,mode,choice,index:0,lines,revealed:false};openModal(CITY_STORIES[port].npc,'CONVERSATIONS ASHORE',dialogueHTML(),'dialogue');typeDialogue();if(sound)sound.fx('page');}
function advanceDialogue(){if(!dialogue)return;if(!dialogue.revealed){revealDialogue();return;}if(dialogue.index<dialogue.lines.length-1){dialogue.index++;replaceBody(dialogueHTML());typeDialogue();if(sound)sound.fx('page');}}
const illustratedOpenModal=openModal;
openModal=function(title,eyebrow,body,type,locked=false){if(type!=='dialogue'){stopDialogueTyping();dialogue=null;}illustratedOpenModal(title,eyebrow,body,type,locked);$('modal').classList.toggle('dialogue-modal',type==='dialogue');$('modal').classList.toggle('wide-modal',['atlas','storyHub','achievements','research','people','dialogue','ports'].includes(type));};
const illustratedCloseModal=closeModal;
closeModal=function(force=false){if(modalLocked&&!force)return;stopDialogueTyping();dialogue=null;illustratedCloseModal(force);};
const illustratedShowEvent=showEvent;
