let surveyRun=null,surveyTimer=null,surveySerial=0;
const TOPIC_NAMES={history:'港口历史',trade:'贸易与工艺',culture:'当地生活与文化',nature:'海路与自然环境',work:'我们的委托',complete:'递交报告',greeting:'码头相逢'};
function stopSurveyAnimation(){if(surveyTimer!==null)clearTimeout(surveyTimer);surveyTimer=null;}
function surveyGoalLink(port){if(game.s.voyage)return'<span class="objective-hint">抵港后开展考察</span>';return port===game.s.port?'<button class="small-button" data-action="survey">前往考察 ↗</button>':`<button class="small-button" data-story-nav="${port}">前往${PORT_BY_ID[port].name} ↗</button>`;}
const v4StoryHTML=storyHTML;
storyHTML=function(port){let html=v4StoryHTML(port);const r=game.s.cityStories[port],chapter=CITY_STORIES[port].chapters[Math.min(r?.stage||0,1)];if(r?.stage!==2){for(const goal of chapter.goals.filter(g=>g.type==='survey')){const o=game.objective(goal,port),old=`<span>${o.label}</span><b>${Math.min(o.value,o.target)} / ${o.target}</b>`;html=html.replace(old,old+surveyGoalLink(port));}}return html;};
surveyHTML=function(){const p=PORT_BY_ID[game.s.port],v=game.surveyPreview(),species=MARINE_SPECIES.filter(a=>a.regions.includes(p.region)),story=game.surveyObjectives(p.id);return`<div class="survey-landscape">${painting('port:'+p.id,p.name)}<div><small>FIELD EXPEDITION · ${p.region}</small><h3>${p.name}的岸上与潮间</h3><p>${p.desc}</p></div></div><div class="survey-brief"><div class="survey-stats"><span>时间 <b>1 天</b></span><span>补给 <b>4 单位</b></span><span>本次工资 <b>${v.wage} G</b></span><span>本地考察 <b>${v.count} 次</b></span></div><p class="field-duty">${v.officer}值勤 · ${v.perk}<br>本次士气预计 +${v.morale}${v.extraKnowledge?'，额外学识 +'+v.extraKnowledge:''}。${v.wage===0?'现有金币不足支付当日工资，沿用航程规则，本次不扣工资。':''}</p><div class="field-note"><small>领航员的线索</small><p>记录城市遗产，观察潮汐与近岸生命。${species.length?'本海区可寻找：'+species.map(a=>a.name).join('、')+'。':'这次可以积累当地的水文与文化记录。'}博物学研究提高发现效率。没有新物种时仍积累学识，考察次数照常计入任务。</p></div>${story?`<div class="survey-task-note"><small>关联篇章 · ${story.title}</small>${story.goals.filter(o=>o.type==='survey').map(o=>`<p>${o.label} <b>${Math.min(o.value,o.target)} / ${o.target}</b></p>`).join('')||'<p>这次考察会计入当地记录，供后续篇章使用。</p>'}</div>`:''}<div class="event-actions"><button class="primary" data-action="do-survey" ${v.canStart?'':'disabled'}>整理行囊 · 开始考察</button>${game.s.supplies<4?'<button class="secondary" data-action="survey-refill">补充物资</button>':''}<button class="secondary" data-story="${p.id}">查看城市篇章</button></div>${v.reason?`<p class="survey-warning" role="status">${v.reason}</p>`:''}</div>`;};
showSurvey=function(){if(game.s.voyage){toast('抵达港口后再组织近岸考察；航行中会自动记录海域。');return;}stopSurveyAnimation();surveyRun=null;openModal('组织一次近岸考察','OBSERVE · RECORD · DISCOVER',surveyHTML(),'survey');};
function surveyResultHTML(report){const p=PORT_BY_ID[report.port],delta=report.deltas,story=report.story,sign=n=>n>0?'+'+fmt(n):fmt(n);return`<div class="expedition-result"><span class="eyebrow">FIELD REPORT · ${p.name}</span><h3>${report.discoveries.length?'把新的世界，写进航海日志。':'每一次观察，都有它的收获。'}</h3><p>这是在${p.name}的第 ${report.count} 次考察。记录已保存。</p></div><div class="survey-stats survey-settlement" aria-live="polite">${[['day','航海日','天'],['supplies','补给',''],['gold','金币','G'],['morale','士气',''],['knowledge','学识','']].map(([key,label,unit])=>`<span>${label}<b>${sign(delta[key])} ${unit}</b></span>`).join('')}</div><div class="atlas-grid result-grid">${report.discoveries.map(id=>{const d=DISCOVERY_BY_ID[id];return`<button class="atlas-card recorded" data-entry="${id}">${entryArt(d)}<div class="atlas-card-copy"><small>${kindLabels[d.kind]}</small><h3>${d.name}</h3><p>新增记录 · 查看详情 ↗</p></div></button>`;}).join('')}</div>${story?`<section class="survey-task-note"><small>篇章进度 · ${story.title}</small>${story.goals.map(o=>`<p class="${o.ready?'goal-ready':''}">${o.ready?'◆':'◇'} ${o.label}<b>${Math.min(o.value,o.target)} / ${o.target}</b></p>`).join('')}<p>${story.ready?'全部目标已满足，可以递交报告。':'尚有目标未完成，返回篇章查看下一步。'}</p></section>`:'<p class="market-foot">当地考察次数已累计。可以在城市篇章中结识联系人，开启当地故事。</p>'}<div class="event-actions"><button class="primary" data-action="survey-again">继续考察</button>${story?.ready&&story.stage===0?`<button class="primary" data-talk-complete="${p.id}">递交报告</button>`:''}<button class="secondary" data-story="${p.id}">${story?.ready&&story.stage===1?'返回篇章 · 选择回报':'返回城市篇章'}</button><button class="secondary" data-action="atlas">查看图鉴</button></div>`;}
function finishSurveyAnimation(){stopSurveyAnimation();if(!surveyRun)return;surveyRun.phase='result';if(currentModal==='survey'){modalLocked=false;$('closeModal').hidden=false;replaceBody(surveyResultHTML(surveyRun.report));$('modalBody').scrollTop=0;}}
performSurvey=function(){if(currentModal!=='survey'||surveyRun)return;const ids=safe(()=>game.survey());if(ids===null)return;surveyRun={id:++surveySerial,phase:'animation',report:game.lastSurveyReport};const current=surveyRun;modalLocked=true;$('closeModal').hidden=true;replaceBody(`<div class="expedition-animation">${painting('port:'+current.report.port,PORT_BY_ID[current.report.port].name)}<div class="expedition-animation-shade"></div><div class="field-compass">${icon('compass')}</div><div class="expedition-animation-copy"><small>正在整理${PORT_BY_ID[current.report.port].name}的记录</small><h3>循着潮声，留意世界。</h3><p>考察已结算；这段演出不会额外消耗资源。</p><button class="secondary" data-action="survey-skip">跳过动画 · 查看报告</button></div></div>`);if(sound)sound.fx('discovery');if(!game.s.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches){finishSurveyAnimation();return;}surveyTimer=setTimeout(()=>{if(surveyRun===current)finishSurveyAnimation();},1700);};
const v4ModalOpen=openModal,v4ModalClose=closeModal;
openModal=function(title,eyebrow,body,type,locked=false){if(type!=='survey')stopSurveyAnimation();const notice=$('discoveryNotice');if(notice&&!notice.hidden){notice.hidden=true;clearTimeout(noticeTimer);if(notice._notice)game.notices.unshift(notice._notice);}v4ModalOpen(title,eyebrow,body,type,locked);};
closeModal=function(force=false){if(modalLocked&&!force)return;stopSurveyAnimation();v4ModalClose(force);};
const v4ConversationLines=conversationLines;
conversationLines=function(port,mode){
 const lore=typeof CITY_LORE!=='undefined'?CITY_LORE[port]:null;if(lore?.topics?.[mode])return lore.topics[mode].lines;
 const record=game.s.cityStories[port],stage=Math.min(record?.stage||0,1),chapter=CITY_STORIES[port].chapters[stage];
 if(mode==='complete'&&record?.stage===2)return[{id:port+':complete:done',who:'npc',text:DIALOGUES[port].ending}];
 const lines=v4ConversationLines(port,mode);
 if(lore&&(mode==='work'||mode==='greeting')&&record?.stage!==2){
  lines.push({who:'npc',text:lore.chapters[stage]});
  const goals=chapter.goals.map(g=>game.objective(g,port));
  lines.push({who:'captain',text:(record?'我来核对已经完成的部分：':'在接受之前，我想先确认约定：')+goals.map(o=>o.label+'（'+Math.min(o.value,o.target)+' / '+o.target+'）').join('；')+'。'});
  lines.push({who:'npc',text:record?(goals.every(o=>o.ready)?'所有目标都已满足。回到篇章递交报告，就能确认下一步；回报仍由你亲自选择。':'还有未完成的部分。考察需要在这里停泊后组织；交付要留有实物；访问与出售则依照目标地点累计。'):'你可以先看看城市，也可以接受这份委托。接下以后，篇章里会保留清单，告诉你每一项实际推进了多少。'});
 }
 if(lore&&mode==='complete')lines.push({who:'npc',text:stage===0?'你已经让最初的准备落地。'+lore.chapters[1]:CITY_STORIES[port].ending},{who:'captain',text:stage===0?'我会把下一章的目标重新看清，再安排航程。已经做过的访问与地方记录不会丢失。':'这段联系已经有了扎实的基础。我会亲自确认回报，让接下来的商路或知识交流继续服务于彼此。'});
 return lines.map((line,index)=>({...line,id:port+':'+mode+':'+stage+':'+index}));
};
function dialogueTopicButtons(){if(dialogue.remote)return'';return`<nav class="dialogue-topics" aria-label="港口话题">${LORE_TOPIC_IDS.map(id=>`<button class="${dialogue.mode===id?'active':''}" data-dialogue-topic="${id}" ${(typeof CITY_LORE==='undefined'||!CITY_LORE[dialogue.port])&&id!=='history'?'disabled':''}>${TOPIC_NAMES[id]}${game.s.conversations[dialogue.port]?.topics?.[id]?.read?' · 已阅':''}</button>`).join('')}<button data-dialogue-topic="work" class="${dialogue.mode==='work'?'active':''}">我们的委托</button></nav>`;}
function dialogueActionsHTML(){const t=dialogue,r=game.s.cityStories[t.port],ch=CITY_STORIES[t.port].chapters[r?.stage],ready=ch&&ch.goals.every(g=>game.objective(g,t.port).ready);return`<div class="dialogue-options">${t.mode==='complete'&&ch?`<button class="primary" data-dialogue-submit="true" ${ready?'':'disabled'}>${r.stage===1?(t.choice==='merchant'?'开拓商路 · 领取回报':'分享知识 · 领取回报'):'递交报告 · 完成本章'}</button>`:!r&&!t.remote?'<button class="primary" data-dialogue-accept="true">接受这份委托</button>':r?.stage<2?'<button class="primary" data-dialogue-goals="true">查看当前目标</button>':''}<button class="secondary" data-dialogue-goals="true">返回城市篇章</button></div>`;}
function dialogueSourceHTML(){const topic=typeof CITY_LORE!=='undefined'?CITY_LORE[dialogue.port]?.topics[dialogue.mode]:null;if(!topic)return'';const sources=CITY_LORE[dialogue.port].sources;return`<details class="dialogue-sources"><summary>史料与画作说明 · ${topic.period}</summary><p>历史札记注明年代；交谈人物与委托属于原创虚构剧情，引用资料并非角色当年的现场记录。</p>${sources.map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title)} ↗</a>`).join('')}${artCredit('port:'+dialogue.port)}</details>`;}
dialogueHTML=function(){const t=dialogue,p=PORT_BY_ID[t.port],st=CITY_STORIES[t.port],line=t.lines[t.index],full=t.view==='full';return`<div class="dialogue-stage ${full?'dialogue-reading':''}">${painting('port:'+p.id,p.name,'dialogue-backdrop')}<div class="dialogue-vignette"></div><div class="dialogue-location"><small>${p.nation}</small><strong>${p.name}</strong><span>${dateText(game.s.day)}</span></div><div class="dialogue-cast"><div class="dialogue-person">${painting('crew:captain','船长阿尔瓦罗',`dialogue-portrait captain-portrait ${line.who==='captain'?'speaking':''}`)}<span class="dialogue-person-name">阿尔瓦罗 · 船长</span></div><div class="dialogue-person">${painting('npc:'+p.id,st.npc,`dialogue-portrait npc-portrait ${line.who==='npc'?'speaking':''}`)}<span class="dialogue-person-name" title="${escapeHTML(st.npc)}">${escapeHTML(st.npc)}</span></div></div><div class="dialogue-box"><div class="dialogue-speaker"><strong>${full?'港口谈话录':line.who==='npc'?st.npc:'阿尔瓦罗 · 德·索萨'}</strong><span>${t.remote?'港际信使 · ':''}${TOPIC_NAMES[t.mode]||t.mode} · ${full?'完整内容':t.index+1+' / '+t.lines.length}</span></div>${dialogueTopicButtons()}<div class="dialogue-scroll" tabindex="0" aria-label="对话内容">${full?`<div class="dialogue-transcript">${t.lines.map((l,i)=>`<article class="transcript-line ${l.who}" data-line-id="${escapeHTML(l.id||t.port+':'+t.mode+':'+i)}"><strong>${l.who==='npc'?st.npc:'阿尔瓦罗 · 德·索萨'}</strong><p>${escapeHTML(l.text)}</p></article>`).join('')}</div>${dialogueSourceHTML()}`:'<p id="dialogueText" class="dialogue-text" aria-live="off"></p>'}</div><div class="dialogue-reading-tools">${full?'<button class="text-button" data-dialogue-view="step">← 返回逐句对话</button>':'<button id="revealSentence" class="text-button" data-dialogue-reveal="true">立即显示本句</button><button class="text-button" data-dialogue-view="full">显示完整内容 ↗</button>'}</div><div class="dialogue-controls">${full||t.index===t.lines.length-1?dialogueActionsHTML():'<button class="primary" data-dialogue-next="true">继续对话 <span>↵</span></button>'}</div></div></div>`;};
function noteDialogueReading(all=false){if(!dialogue||dialogue.remote)return;game.noteReading(dialogue.port,dialogue.mode,dialogue.index,all||dialogue.index===dialogue.lines.length-1);saveGame();}
typeDialogue=function(){stopDialogueTyping();if(!dialogue||currentModal!=='dialogue'||dialogue.view==='full')return;const active=dialogue,text=active.lines[active.index].text,el=$('dialogueText'),button=$('revealSentence');if(!el)return;if(active.cursorIndex!==active.index){active.cursor=0;active.cursorIndex=active.index;}active.cursor=active.cursor||0;const instant=game.s.settings.instantText||!game.s.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;if(instant)active.cursor=text.length;active.revealed=active.cursor>=text.length;el.textContent=text.slice(0,active.cursor);el.setAttribute('aria-label',text);if(button)button.hidden=active.revealed;if(active.revealed){noteDialogueReading();return;}dialogueTimer=setInterval(()=>{if(dialogue!==active||currentModal!=='dialogue'||active.view==='full'){stopDialogueTyping();return;}active.cursor=Math.min(text.length,active.cursor+1);el.textContent=text.slice(0,active.cursor);if(active.cursor%12===0&&sound)sound.fx('quill');if(active.cursor===text.length){active.revealed=true;if(button)button.hidden=true;stopDialogueTyping();noteDialogueReading();}},30);};
revealDialogue=function(){if(!dialogue||dialogue.view==='full')return;stopDialogueTyping();const text=dialogue.lines[dialogue.index].text;dialogue.cursor=text.length;dialogue.cursorIndex=dialogue.index;dialogue.revealed=true;const el=$('dialogueText');if(el)el.textContent=text;const button=$('revealSentence');if(button)button.hidden=true;noteDialogueReading();};
